programs.sol:
"""Approximate a local, spelling-sensitive 'not' / 'ot' response.

The strongest negative rule is 'not' after a comma or clause-breaking dash.
Ordinary auxiliary + not constructions suppress it. Short ot-centered pieces
also respond to their preceding consonant (including Cyrillic spellings).
Split t-pieces can complete the same pattern across a token boundary.
All other tokens get zero. A 0.9 shrinkage reflects missing lexical context;
these are surface-form rules, not a general detector of semantic negation.
"""
READS = ()

AUXILIARIES = set('is are was were am have has had '
                  'will would should may might do does did'.split())
CONDITIONALS = set('if why when'.split())
WEAK_MODALS = set('could must need shall'.split())
PRONOUNS = set('i you he she it we they its'.split())
ADVERBS = set('probably perhaps maybe often still also really'.split())
CONTRACTIONS = {"'s", "'m", "'re", '’s', '’m', '’re'}


def predict(token, previous):
    word = previous.strip().lower()
    if token == ' not':
        if previous.rstrip('\"\'').endswith((',', ';', '—', '–', '--')):
            return -6.8
        if word in AUXILIARIES or word in CONTRACTIONS:
            return 0.05
        if word in CONDITIONALS or word in WEAK_MODALS:
            return -0.3
        if word in PRONOUNS or word.endswith('ly'):
            return -0.6
        if word in ADVERBS:
            return -1.2
        if word in {'be', 'of', 'for', 'while'}:
            return -1.2
        if word == 'or':
            return -0.5
        if word == 'to':
            return -1.05
        if word in {'and', 'but', 'as', 'can'}:
            return -2.0
        return -2.5

    # A split 't' piece can complete the same spelling across a token break.
    if (token.lower().startswith('t') and len(token) <= 4
            and previous.lower().endswith(('no', 'ro'))):
        return -6.5 if previous.lower().endswith('no') else -3.0

    bare = token.lstrip(' /_-')
    lower = bare.lower()
    spaced = token.startswith(' ')
    if lower in {'not', 'note', 'notes', 'nota'}:
        if lower != 'not':
            if bare == 'Note':
                return 0.0
            return -0.5 if spaced else -3.0
        if token.startswith(('/', '_')):
            return -1.8
        if bare.isupper():
            return -1.2 if spaced else -2.5
        if bare[:1].isupper():
            return -2.85 if spaced else -2.25
        if '\n' in previous:
            return -0.7
        if previous.endswith('('):
            return -4.8
        return -3.8

    # Short syllables; do not fire on full words such as 'other' or 'hotel'.
    if lower in {'ot', 'ota', 'ote', 'oto', 'ots', 'ott', 'otta',
                 'otte', 'otic', 'otropic', 'oth', 'от'}:
        if spaced:
            return 0.1
        if lower.startswith('oth'):
            return -0.8
        consonant = previous[-1:].lower()
        if not consonant:
            return 0.0
        if consonant in 'nн':
            value = -0.5 if lower == 'ote' else -5.9
        elif consonant in 'rр':
            value = -2.4
        elif consonant in 'dд':
            value = -1.1
        elif consonant in 'lл':
            value = -0.7
        elif consonant in 'ckк':
            value = 4.6
            if len(previous.strip()) == 1 or lower == 'ott':
                value = 1.5
        elif consonant == 'м':
            value = 1.4
        elif consonant == 'm':
            value = 0.6 if lower == 'oto' else 3.5
        elif consonant in 'pпbбgг':
            value = 2.8
        elif consonant in 'sсzз':
            value = 1.8
        elif consonant == 'e':
            value = -3.0 if lower == 'ot' else 0.0
        else:
            value = 0.0
        return value

    if lower == 'got' and spaced:
        return 0.0
    if lower in {'rot', 'pot', 'bot', 'cot', 'got'}:
        if lower == 'rot':
            return -0.8 if spaced else -2.5
        return 0.8 if spaced else 1.8
    return 0.0


def step(carry, prefix, upstream):
    previous = ''
    if (prefix.position and
            prefix.document_ids[-2] == prefix.document_ids[-1]):
        previous = prefix.token_strings[-2]
    return None, 0.9 * float(predict(prefix.token_strings[-1], previous))

programs.haiku:
"""Contrastive "not" detector for layers.1.mlp.down_proj:960.

The component goes strongly negative on a bare "not" (or "Not") that is not
negating a verb: the contrastive "not" in "X, not Y", "(not ...)", "but not",
"and not", or "Not" after a full stop. After an auxiliary ("is not", "do not",
"did not") it stays near zero. Subword "ot" pieces (Huguenot, Dakota) are
mixed in sign and are left at zero here.
"""

READS = ()

NOT_WORDS = {" not", "not", " Not", "Not", " NOT"}
AUXILIARIES = {
    " is", " are", " was", " were", " be", " been", " am", " do", " does", " did",
    " has", " have", " had", " may", " might", " will", " would", " shall",
    " should", " could", " can", " must", " need", "'s", "'m", "'re", "’s", "’re",
}
PUNCTUATION_BEFORE = {",", "(", "?", ":", ";", ")", "—", "–", " —", " –", " -", "-"}
CONJUNCTIONS = {" but", " and", " or", " only", " just", " rather", " to"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token not in NOT_WORDS or len(prefix.token_strings) < 2:
        return carry, 0.0
    if prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, -2.5
    before = prefix.token_strings[-2]
    if before in AUXILIARIES:
        value = 0.0
    elif before in PUNCTUATION_BEFORE:
        value = -6.0
    elif before in CONJUNCTIONS:
        value = -2.0
    elif before == ".":
        value = -3.0
    else:
        value = -1.0
    return carry, value

programs.sol:
"""Boundary-sensitive text markers, with a near-zero background.

The largest predictable spikes are the colon in a document-initial
'Title:' header and initial function declarations. Import declarations
and initial chat markers have the opposite sign. Small grammatical
biases cover modal verbs, auxiliaries, logical connectives and sameness
words. Most other tokens remain near zero. This is a partial
approximation, not a claim that all lexical variation is explained.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        position, first = 0, token
    else:
        position, first = carry[1] + 1, carry[2]
    word = token.strip()
    value = 0.001
    # Small background biases for ordinary grammatical categories.
    if word in {'can', 'could', 'may', 'might', 'must', 'shall',
                'should', 'will', 'would'}:
        value = -0.016
    elif word in {'was', 'were', 'did', 'had'}:
        value = -0.011
    elif word in {'has', 'does'}:
        value = -0.025
    elif word in {'not', 'no', 'never', 'neither', 'nor', 'none'}:
        value = 0.013
    elif word in {'or', 'either'}:
        value = -0.015
    elif word in {'and', 'both'}:
        value = 0.008
    elif word in {'same', 'similar', 'identical', 'equivalent'}:
        value = 0.05
    elif word == '(':
        value = 0.01
    elif word == ')':
        value = -0.009
    elif token == '<|im_start|>':
        value = 0.015
    elif token == '<|im_end|>':
        value = -0.045
    elif token == '<think>':
        value = 0.066
    if position == 0:
        if token in {'<|im_start|>', '<|im_end|>', '<think>', '</think>',
                     '<tool_call>', '</tool_call>', '<tool_response>',
                     '</tool_response>'}:
            value = -0.27
        elif token == '<|endoftext|>':
            value = 1.677
        elif word.lower() in {'not', 'no', 'never', 'neither', 'nor', 'none'}:
            value = -0.4
        elif token == 'Title':
            value = 0.608
        elif token == 'void':
            value = 3.065
        elif token in {'function', '(function', 'func'}:
            value = 0.94
        elif token in {'int', 'char', 'def', 'class'}:
            value = 0.55
        elif token in {'package', 'import'}:
            value = -0.74
        elif token == 'from':
            value = -0.254
        elif token.isdecimal():
            value = 0.15
        elif token == '\t':
            value = 0.59
        elif token == '\xa0':
            value = 0.88
    elif position == 1:
        if first == 'Title' and token == ':':
            value = 4.297
        elif first == '(function' and token.strip() == '()':
            value = 2.305
        elif token.isdecimal():
            value = 0.055
    return (document, position, first), value

"""Detect short lic/lich/lik/lig-shaped subwords and split spellings.

German -lich and Dutch -lijk are typical examples. Split lit/leit
completions instead get negative values. Complete 'public' and 'like'
receive weaker rules based on case, adjacent whitespace and word joining.
A few corresponding non-Latin letter patterns are included. This is a
local spelling approximation, not a semantic or language classifier.
Unmatched inputs receive a small baseline of 0.002.
"""
import re

READS = ()
DIRECT = re.compile(
    r'^((?:ub|[oeug])?)(l(?:ei|ij|i|y)(?:ch|ck|qu|[ckgqx]))(.*)$'
)
SPLIT = re.compile(r'^([iy](?:jk|ch|ck|qu|[ckgqx]))(.*)$')
# Small inflections, not arbitrary continuations such as '-lication'.
ENDINGS = {'', 'a', 'as', 'e', 'en', 'er', 'ern', 'es', 'o', 'os',
           's', 't', 'keit', 'it', 'ity'}


def response(s, previous):
    text, before = s.lower(), previous.lower()
    word = text.strip(' -/\t_')
    if word == 'public':
        if s.startswith('\t'):
            return 0.0
        if s.strip(' -/\t_') != word:
            return 2.4
        return 0.3 if previous.isspace() or not s.startswith(' ') else 1.7
    if word == 'like':
        if s.startswith('-') or before.endswith(' the'):
            return 0.5 if s.startswith('-') else 1.1
        return 1.2 if s[:1].isalpha() and previous[-1:].isalpha() else 0.1
    if word == 'litt':
        return -4.2
    if not s[:1].isalpha():
        m = DIRECT.fullmatch(text[1:]) if s.startswith(' ') else None
        return 2.0 if m and not m[1] and not m[3] else 0.002

    m = DIRECT.fullmatch(text)
    if m and m[3] in ENDINGS:
        _, core, ending = m.groups()
        if before.endswith('l'):
            return 4.0
        if ending in ('t', 'it', 'ity'):
            return 0.9
        if core.startswith('lei'):
            return 1.3
        if core.endswith(('ch', 'qu')):
            return 4.3
        if core.endswith('ck'):
            return 0.0 if before.endswith('c') else 1.9
        return 2.7 if ending in ('a', 'as', 'e', 'o', 'os') else 3.6

    if before.endswith(('l', 'le')):
        m = SPLIT.fullmatch(text)
        if m and m[2] in ENDINGS | {'u', 'g', 'h', 'y', 'i', 'n'}:
            core, ending = m.groups()
            if core.endswith('ch'):
                if ending == 't':
                    return 2.0
                return 3.0 if before.endswith('le') else 9.1
            return 2.0 if core.startswith('y') else 3.3
        if re.fullmatch(r'it(?:t|is|en|y|et|em|an)?', text):
            if before.strip() == 'l':
                return -3.3
            return -2.5 if before.endswith('le') else -0.3
    if re.search(r'l(?:[iy]|ij)$', before):
        if re.fullmatch(r'(?:[ckgqx]|ch|ck)(?:a|e|en|er|s|o)?', text):
            return 2.2
        if text in ('t', 'tt'):
            return -0.9
    if before.endswith('lic') and text in ('h', 'hs'):
        return 5.7

    # Corresponding Cyrillic syllables and a few loanword letter sequences.
    if text in ('лич', 'лик'):
        return 2.4
    if before.endswith(('л', 'ль')) and text.startswith(('ич', 'ик', 'нич')):
        return 4.0
    if before.endswith(('ли', 'лы', 'лі')) and text.startswith(('к', 'ч', 'г')):
        return 1.8
    if before.endswith('リ') and text.startswith('ー'):
        return 4.0 if before == 'リ' and '�' in text else 0.2
    if before.endswith('리') and text.startswith('케'):
        return 4.5
    return 0.002


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    token = prefix.token_strings[-1]
    return (document, token), response(token, previous)

"""Approximate a NUL-padding detector, with a document-start correction.

NUL bytes, as in UTF-16 text read as plain bytes, respond most strongly
following letters, less following digits, and least following spaces.
Letter case and vowels refine this response. Letters following NULs have
a small negative response; spaces there have a small positive response.
Other ordinary text is approximated by zero.
At document starts use a negative baseline (stronger for unspaced title-case
words), except for the strongly positive end-of-text marker.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    token = prefix.token_strings[-1]
    value = 0.0
    if first:
        value = -0.22
        if token.isspace():
            value = -0.05
        elif token.isalpha() and token.istitle() and not token.isupper():
            value = -0.60
    if token == '<|endoftext|>':
        value = 1.674 if first else 0.0
    elif token == '\x00':
        previous = previous[-1:]
        if previous.isalpha():
            if previous.isupper():
                value = 2.0
            elif previous.lower() in 'aeiou':
                value = 2.53
            else:
                value = 2.37
        elif previous.isdigit():
            value = 1.88
        elif previous == ' ':
            value = 0.40
        elif previous == '\n':
            value = 0.93
        elif previous in ('.', '\r'):
            value = 1.36
        else:
            value = 1.1
    elif previous == '\x00':
        if token.isalpha():
            value = -0.05
        elif token == ' ':
            value = 0.022
        elif token in (',', '.', '\r'):
            value = -0.04
    return (doc, token), value

"""Sparse local spelling and phrase rules, rather than a general semantic model.

Positive pulses mark dental-letter joins, several 'at' constructions, typed
container names, and Japanese freshly-completed expressions. Correct-answer
phrases and PHP opening tags get negative pulses. Uncovered responses stay zero.
Only the preceding token and a short spelling tail are retained per document.
"""
import re

READS = ()
WORD_END = re.compile(r'[^\W\d_]+$')
VALUATION = {'valued', 'estimated', 'priced', 'appraised'}
PLACEMENT = {'located', 'situated', 'positioned'}
STARTING = {'start', 'starts', 'started', 'starting', 'begin', 'begins',
            'beginning'}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous, tail = ('', '') if carry is None or carry[0] != doc else carry[1:]
    p = previous.strip().lower()
    value = 0.0

    # A final t joined to a d-final spelling, especially in proper names.
    if p.isalpha() and p.endswith('d') and s == 't':
        value = 1.5
        if p.endswith(('nd', 'ld')):
            word = WORD_END.search(tail)
            value = 6.0 if word and word[0][0].isupper() else 3.5

    # TypedDict / TypedArray and ndarray-style compound type names.
    if previous.endswith('yped') and s in {'Dict', 'Array'}:
        if s == 'Dict':
            value = 10.0 if previous == 'yped' else 5.5
        else:
            value = 4.5 if previous == 'yped' else 3.2
    elif p.endswith('nd') and s in {'array', 'arrays'}:
        value = 1.0
    elif s == ' at':
        if p in VALUATION:
            value = 4.0
        elif p in {'centered', 'centred'}:
            value = 2.8
        elif p in PLACEMENT or p in STARTING:
            value = 0.8
    elif s == ' list' and p in {'ordered', 'sorted'}:
        value = 1.8
    elif s in {' answer', ' answers'} and p in {'correct', 'right'}:
        value = -1.5
    elif previous == '<?' and s == 'php':
        value = -1.4

    # -ta-te and -ta-bakari: freshly / just completed, in Japanese.
    if previous.endswith('た') and s in {'て', 'ばかり'}:
        value = 10.0 if s == 'て' else 4.0
    elif previous == 'た' and s == 'ま':
        value = 2.8  # beginnings of tama-ni and tama-tama
    return (doc, s, (tail + s)[-48:]), value

"""A local grammatical signal: auxiliaries immediately after their subjects.

Present-tense be/have and future will are strongly negative after personal
pronouns, especially I, we, and you. Plural demonstratives/relatives before
are instead give a positive signal. Inverted do/modal questions suppress
the finite-have rule; have/'ve got is negative too. Separate small rules
cover Android/testing imports and Java annotations or return types.
Most other tokens are quiet.
"""
READS = ()


def predict(token, previous, before=""):
    word = token.strip().lower()
    subject_text = previous.strip().lstrip("\"'“‘([{>:")
    subject = subject_text.lower()
    capital = subject_text[:1].isupper()
    attached = bool(previous) and not previous[0].isspace()
    value = 0.0
    if word == 'are':
        value = {'we': -3.4, 'you': -3.1, 'they': -1.0,
                 'i': -0.7, 'that': 0.8, 'these': 0.4,
                 'those': 0.4, 'which': 0.35, 'what': 0.45,
                 'here': 1.8}.get(subject, 0.0)
        if subject == 'we':
            value -= 0.7 * capital + 0.8 * attached
        elif subject == 'you':
            value -= 0.9 * attached
    elif word == 'have':
        value = {'i': -2.8, 'you': -2.8, 'we': -2.65,
                 'they': -1.15, 'who': -0.35,
                 'that': 0.2, 'which': 0.15}.get(subject, 0.0)
        if subject in ('i', 'you'):
            value -= 0.85 * attached
        elif subject == 'we':
            value -= 0.35 * capital + 0.2 * attached
    elif word == 'am' and subject == 'i':
        value = -3.65 - 0.9 * attached - 0.9 * (not capital)
    elif word == 'will':
        value = {'i': -1.4, 'you': -3.8, 'we': -2.1,
                 'they': -1.1, 'he': -1.15, 'she': -1.15,
                 'who': -0.95, 'it': -0.3, 'there': -0.2,
                 'which': -0.33, 'what': -0.65,
                 'this': 0.2, 'that': 0.28}.get(subject, 0.0)
    elif word == 'is':
        if subject in ('it', 'that'):
            value = -0.67 - 0.12 * capital
        elif subject in ('he', 'she', 'who'):
            value = -0.56
        elif subject in ('this', 'there', 'what', 'here'):
            value = -0.26
        elif subject == 'which':
            value = -0.13
    elif word == 'has':
        if subject in ('he', 'she'):
            value = -0.33
        elif subject in ('it', 'that', 'who', 'this'):
            value = -0.2
    # Inverted questions: 'do you have' is not a finite 'you have'.
    if word == 'have' and subject in ('i', 'you', 'we', 'they'):
        if before.strip().lower() in INVERTING_AUXILIARIES:
            value = 0.0
    if word == 'got' and previous.strip().lower() in ("'ve", '’ve', 'have'):
        value = -1.9
    return value + code_phrase(token, previous)


INVERTING_AUXILIARIES = {
    'do', 'does', 'did', 'can', 'could', 'will', 'would',
    'shall', 'should', 'may', 'might', 'must',
}


def code_phrase(token, previous):
    """Smaller, independent responses to code namespaces and documentation."""
    word, prev = token.strip(), previous.strip()
    if prev == 'import':
        return {'android': 5.25, 'androidx': 4.4}.get(word, 0.0)
    if prev == 'org':
        return {'.junit': 7.6, '.testng': 3.2,
                '.json': 2.25}.get(word, 0.0)
    if prev in ('.junit', '.testng'):
        return {'.Assert': 9.5, '.Test': 8.0}.get(word, 0.0)
    if prev.endswith('@'):
        return {'param': -2.0, 'author': -1.4,
                'Test': 2.0, 'NonNull': 4.0,
                'Nullable': 5.0}.get(word, 0.0)
    if prev == 'public' and word in ('int', 'bool', 'boolean'):
        return 2.4
    return 0.0


def step(carry, prefix, upstream):
    previous = ''
    if len(prefix.token_ids) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            previous = prefix.token_strings[-2]
    before = ''
    if len(prefix.token_ids) > 2:
        if prefix.document_ids[-1] == prefix.document_ids[-3]:
            before = prefix.token_strings[-3]
    return None, predict(prefix.token_strings[-1], previous, before)

"""Respond to ET and ETT(E) endings of an unfinished word.

The response is strongest when a token continues a word with these spellings.
Word length, the fragment's English frequency, and an adjacent vowel adjust
its strength. Other spellings are mostly silent. There are separate negative
responses for the first token and for runs of middle dots.
"""
import re
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=32768)
def frequency(fragment):
    return zipf_frequency(fragment, 'en')


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    previous = '' if first else carry[1]
    raw = prefix.token_strings[-1]
    token = anyascii(raw).lower()
    continues = bool(token and token[0].isalpha() and previous)
    combined = (previous + token if continues else token).strip()
    word = re.split('[^a-z]', previous + token if continues else token)[-1]
    state = (document, word)

    if len(raw.strip()) > 1 and set(raw.strip()) == {'·'}:
        value = -2.04
    elif combined.endswith(('ett', 'ette', 'etta', 'etto', 'etti')):
        value = 2.11 if continues else 0.65
    elif combined.endswith('et'):
        if not continues:
            value = 0.10
        elif len(word) > 8:
            value = 0.31
        elif frequency(token.strip()) <= 4.37:
            if not raw.isascii():
                value = 0.12
            else:
                k = token.rfind('et')
                before = token[k-1:k] if k > 0 else previous[-1:]
                value = 3.58 if before and before in 'aeiou' else 1.74
        else:
            value = 0.96 if any(c in 'aeiou' for c in previous) else -0.17
    else:
        value = -0.31 if first else 0.0
    return state, value

"""Approximate a sparse response to size compounds and mathematical typography.

After standalone 大/小 ('big/small'), dictionary meanings distinguish head
and limb nouns, references to children, names and actions. The strongest
negative typography cases are byte pieces of invisible multiplication
(U+2062) and private-use glyph U+E89E. Doubled middle dots are positive. Coarse document-initial
classes cover a separate start-of-text response. A title-field colon has
its own negative rule; otherwise predict zero.
"""
import re
from functools import lru_cache
import cedict

READS = ()
SIZE_WORDS = {'大', '小', '的大', '的小', '一大', '一小', '大大', '小小'}
FUNCTION_WORDS = {
    'a', 'an', 'the', 'and', 'or', 'to', 'with', 'it', 'they', 'we', 'you'
}
CODE_DECLARATIONS = {'import', 'const', 'var', 'def', '#include'}


@lru_cache(maxsize=2048)
def size_response(size, text):
    big = size == '大'
    if size == '小' and text.startswith('朋友'):
        return -6.15 if text == '朋友' else -3.36
    first = cedict.glosses(text[:1])
    sense = first[0].lower() if first else ''
    core = re.split(r'[;(]', sense)[0].strip()
    if core in {'head', 'hand', 'foot', 'eye'}:
        if len(text) > 1:
            return -1.82 if big else -0.14
        return -4.05 if big else -1.93
    if big and core in {'lamp', 'light'}:
        return -4.0
    if big and core in {'curtain', 'curtain or screen'}:
        return -2.55
    meanings = cedict.glosses(text)
    if meanings and meanings[0].startswith('to '):
        return 0.51 if big else 0.36
    if any(g.startswith('surname ') or 'dynasty' in g for g in meanings):
        return 0.48 if big else 0.19
    return 0.1


def initial_response(text):
    s = text.strip()
    if text.startswith('<|'):
