        value = 3.0
    elif word.endswith('волн') and not old.lower().endswith('волн'):
        value = 3.8 if 'волн' in low else 7.5
    elif old.lower().endswith('вол') and low == 'г':
        value = 2.3
    elif low.strip() == 'wv':
        value = 3.8 if text.isupper() else 5.6
    elif old.lower() == 'w' and low == 'v':
