"""Wave-word detector (layer 1, MLP down-projection component 971).

What it does: this component writes "wave-ness" into the residual stream. It fires on the
word "wave" and its close spellings, on the token that spells the wave:
  - "wave", " Wave", "-wave", and "WAVE" written as W + AVE: strongest (about 9)
  - "waves", "waved", "waveform" (about 7); "av" in "we"+"av" (about 6)
  - "weave" (about 4), "waive"/"waived" (about 3)
  - "wavelength" only weakly (about 2): the wave piece itself is what fires
  - the Chinese/Japanese character 波 (wave) when it stands alone (about 7)
It is 0 everywhere else, including the pieces after the wave (the "front" of wavefront,
the "length" of wavelength), and 波 inside names such as 波兰 (Poland) or 波特 (Potter).

Why: the spelling is read from the current word, so split words such as W+AVE, we+av and
unw+av still fire on the piece that completes the spelling.

Main program: step() reads the newest token. A token that starts with a space or
punctuation starts a word; an all-letter token may continue the word before it.
"""
import re

READS = ()

LETTERS = re.compile(r"[A-Za-z]*$")


def word_before(prefix):
    """Lower-cased letters of the word before the newest token, when the newest token is
    all letters and continues that word (the W of W + AVE); otherwise ''."""
    piece = prefix.token_strings[-1]
    if LETTERS.search(piece).group(0) != piece:
        return ""  # a leading space or punctuation starts a new word
    before = ""
    for i in range(len(prefix.token_strings) - 2, -1, -1):
        if prefix.document_ids[i] != prefix.document_ids[-1]:
            break
        earlier = prefix.token_strings[i]
        letters = LETTERS.search(earlier).group(0)
        before = letters + before
        if letters != earlier:
            break
    return before.lower()


def wave_value(before, new):
    if new == "wave":
        return 9.0
    if new.startswith("wavel"):
        return 2.0  # wavelength
    if new.startswith("wave") or new.startswith("wav"):
        return 7.0  # waves, waved, waveform
    if "weav" in new:
        return 4.0  # weave
    if "waiv" in new:
        return 3.0  # waive
    if new in ("av", "ave", "aver") and before.endswith("w"):
        return 9.0  # the AVE of W + AVE
    if new in ("av", "ave", "aver") and before.endswith("we"):
        return 6.0  # the av of we + av
    return 0.0


def step(carry, prefix, upstream):
    if prefix.token_strings[-1].strip() == "波":
        return None, 7.0  # 波: the wave character, alone
    newest = LETTERS.search(prefix.token_strings[-1]).group(0).lower()
    return None, wave_value(word_before(prefix), newest)

