TEX = re.compile(
    r'\\(?:frac|dfrac|begin|end|int|sum|left|right|notag|text|'
    r'textbf|mathrm|hfill|nonumber|alpha|beta|gamma|partial|sqrt|'
    r'vec|lim|rightarrow|color|hat|qquad|quad|lambda|sigma)\b'
)
