    if token == '3' and text.endswith('\\xa'):  # byte A3, pound sign
        return 0.85
    if '&#' in token or (token == '#' and text.endswith('&')):
        return 0.73
    if token.isdigit() and text.endswith('&#'):
        return 0.48
    if token.isdigit() and re.search(r'&#\d$', text):
        return -0.28
    if "\\'" in token:
        return 0.4
    if token in LATIN1_LEADS:
        return LATIN1_LEADS[token]
    if token.startswith(' ') and token.strip() in LATIN1_LEADS:
        return 0.77 if token.strip() == 'â' else 0.5

    if text.endswith('\\') and token in TEX_COMMAND_PREFIXES:
        return TEX_COMMAND_PREFIXES[token]
