        return -1.85
    if token.isspace() and text.rstrip().endswith('\\\\') and TEX.search(text):
        return -0.73
    if token == ' -' and text.endswith('@@'):  # unified-diff hunk
        return 1.75
    if token == 'index' and text.endswith('\n'):
        return 0.5

    if not text or text.endswith('<|endoftext|>'):
        if token == 'using':
            return 1.96
        if token == 'import':
            return -1.03
        if not text and token == '<|endoftext|>':
            return 3.41
    if token == ':' and (text == 'Title' or text.endswith('<|endoftext|>Title')):
        return -4.75
    return 0.0


