"""Estimate a pulse on a document's first run of identical tokens.

Almost all of the large activations are at document onset. The pulse's
size is not constant: capital letters and short capitalized fragments tend
to be stronger than numbers, punctuation, and very frequent words. These
rules approximate its size using token shape, script, and English word
frequency, not a token-ID lookup. Once a different token appears, return 0.
"""
import math
import regex
from wordfreq import zipf_frequency

READS = ()
COPULA = set('be am is are was were been being'.split())
QUESTION_WORDS = set('who what when where why how which whose whom'.split())
IMPORT_WORDS = set('using import from package namespace include require'.split())
DECLARATIONS = set('public private protected export declare'.split())
SCRIPT_BASE = {
    'Latin': 0.0, 'Han': 5.27, 'Hiragana': 3.29, 'Katakana': 3.90,
    'Hangul': 2.12, 'Cyrillic': 4.58, 'Arabic': 5.49, 'Thai': 4.32,
    'Greek': 1.71, 'Hebrew': 0.0, 'Devanagari': 0.97,
}


def onset_size(text):
    s = text.strip()
    n = len(s)
    if text.startswith('<|'):
        return 6.40 if 'im_start' in text else 3.55
    if not s:
        if '\n' in text:
            return 0.47
        if '\r' in text:
            return 3.71
        if '\t' in text:
            return 1.65
        return 3.35 + 0.19 * math.log1p(len(text))
