             - 0.96 * (frequency < 2) - 1.42 * (frequency > 5.5)
             - 1.04 * (frequency > 6.5) + 2.08 * title * (n <= 3)
             - 1.33 * space * title - 2.34 * (low in COPULA))
    if not space:
        value += 1.45 * title * (low in QUESTION_WORDS)
        value += 1.89 * (low in IMPORT_WORDS) + 7.48 * (low in DECLARATIONS)
    return value


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    token = int(prefix.token_ids[-1])
    if carry is None or carry[0] != doc:
        carry = (doc, token, True, onset_size(prefix.token_strings[-1]))
    elif token != carry[1]:
