"""Component layers.1.mlp.down_proj:976 fires on the first token of each document.

Where a document begins (the token right after <|endoftext|>, or the first token of
the row), it writes a value that depends only on that token's spelling:
- the first letter of the token (ignoring a leading space), via LETTER_VALUE:
  vowels are near 0, while g, h, j, q, z, k, l, y are high;
- +2.4 if the token contains an h anywhere (She, He, Show, hello);
- +11.7 for the digit 7 or the word "seven";
- other tokens (digits, punctuation, emoji, CJK) get OTHER.
Everywhere else in a document the value is 0.

The values are fitted by hand to the activations of the first tokens of documents
in the training data. Scores are weighted by how often each token starts a document.
"""

READS = ()

LETTER_VALUE = {
    "a": 0.4, "b": 2.1, "c": 1.4, "d": 2.0, "e": 0.9, "f": 0.7, "g": 7.0,
    "h": 6.0, "i": 0.1, "j": 6.6, "k": 4.2, "l": 4.0, "m": 1.7, "n": 0.5,
    "o": 0.6, "p": 1.4, "q": 5.8, "r": 1.2, "s": 2.1, "t": -0.6, "u": -0.2,
    "v": 1.8, "w": 1.2, "x": 2.0, "y": 3.5, "z": 7.6,
}
OTHER = 0.3       # first character is not a Latin letter (digit, symbol, CJK, emoji)
H_BONUS = 2.4     # the token contains an h
SEVEN = 11.7      # the token is "7" or "seven"


def first_letter(word):
    """The token's first letter, lowercased, skipping spaces and punctuation; None if none."""
    for ch in word:
        if ch.isalpha():
            return ch.lower() if ch.isascii() else None
    return None


def value_of(word):
    letter = first_letter(word)
    value = LETTER_VALUE.get(letter, OTHER)
    if "h" in word.lower():
        value += H_BONUS
    if word.strip().lower() in ("7", "seven"):
        value += SEVEN
    return value


def step(carry, prefix, upstream):
    t = prefix.position
    starts_document = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not starts_document:
        return None, 0.0
    return None, float(value_of(prefix.token_strings[-1]))

"""Lab-procedure reading of layers.1.mlp.down_proj:978.

The component is quiet in most text. It rises on the words that narrate an experimental
procedure: passive 'was' / 'were' and procedure verbs ('dried', 'stirred', 'conducted',
'carried', 'stopped', 'used', ...), most strongly when a lab cue (a temperature, unit,
reagent or reaction word, or a number) appeared in the last 16 tokens. Prepositions 'at'
and 'by' rise a little in the same context. The first token of each document is pushed
slightly negative. Context resets at each document boundary."""

READS = ()

# Verbs that describe what was done to a sample in a procedure.
PROCEDURE_WORDS = {
    " dried", " stirred", " heated", " conducted", " carried", " stopped", " held",
    " used", " performed", " measured", " evaluated", " modified", " washed",
    " filtered", " mixed", " added", " incubated", " centrifuged", " scanned",
    " collected", " prepared", " obtained", " recorded", " analyzed", " determined",
}
PASSIVE_AUX = {" was", " were"}
PREPOSITIONS = {" at", " by"}

# Words and symbols that signal an experimental setting.
CUES = {
    "°", " °", "C", " C", " hours", " hour", " minutes", " min", " mL", " ml", " mg",
    " μ", "%", " reaction", " mixture", " solution", " sample", " samples",
    " temperature", " reactor", " oven",
}
WINDOW = 16          # how many recent tokens count as the lab context
DOC_START = -0.34    # the first token of a document sits slightly below zero


def step(carry, prefix, upstream):
    new_doc = len(prefix.document_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_doc:
        return [], DOC_START
    recent = [] if carry is None else carry
    tok = prefix.token_strings[-1]
    is_cue = tok in CUES or any(ch.isdigit() for ch in tok)
    in_lab_context = any(recent)
    recent = (recent + [is_cue])[-WINDOW:]
    if tok in PASSIVE_AUX or tok in PROCEDURE_WORDS:
        return recent, (0.75 if in_lab_context else 0.15)
    if tok in PREPOSITIONS:
        return recent, (0.4 if in_lab_context else 0.0)
    return recent, 0.0

