        if s.startswith('\t'):
            after_number = bool(re.fullmatch(r'\s*\d+', line))
            if line.endswith(' ') or after_number:
                value = 1.0 + 0.16 * math.log2(len(s))
                if not s.isspace():
                    value = 0.5 if after_number else 1.2
            elif line.endswith('\t'):
                value = 0.1
            else:
                value = -0.015
        elif s.isspace():
            n = len(s)
            if set(s) == {'\xa0'}:
                if '`' in line:
                    long_run = n >= 3 or line.endswith('\xa0' * 3)
                    value = 0.9 if long_run else 0.2
                else:
                    value = 0.03
            elif '\xa0' in s:
                value = 0.01
            elif line.endswith('\t'):
                value = 1.15 + 0.06 * math.log2(n)
            elif line.endswith('\\n'):
                value = 0.35 if n == 1 else 0.5 if n == 2 else 0.9
            elif LINE_MARGIN.fullmatch(line):
                if n >= 2:
                    value = 0.65
            elif line.endswith(("'", '"')) and n >= 3:
                value = 0.6
            elif not line.strip():
                value = 0.0
