    word = token.strip()
    if word.startswith('<|'):
        return 0.0
    han = bool(regex.search(r'\p{Script=Han}', word))
    spelling = ' '.join(lazy_pinyin(word)) if han else anyascii(word)
    spelling = spelling.lower()
    letters = sum(c.isalpha() for c in spelling)
    count = spelling.count('n')
    density = count / max(1, letters)

    if density < 1 / 8:
        indent = token.strip('\r\n')
        if indent and set(indent) == {' '} and len(indent) % 4 == 0:
            return 1.18
        if word == '9':
            return 0.59
        if count and len(spelling) - spelling.rfind('n') <= 2:
            return 0.27
        return 0.32 if '\ufffd' in token else 0.02

    if density == 1:
        return 1.93
    if density > 0.4:
        return 1.01 if token.startswith(' ') else 1.44

    frequency = zipf_frequency(word.lower(), 'en')
    if frequency > 6.58:
        return 0.07
    if density <= 2 / 9:
        if 'ing' in spelling:
            return 0.19
        if 'ion' in spelling or han:
            return 0.30
        return 0.63
    if letters <= 3:
        return 1.07
    if frequency > 5.65:
        return 0.49
    return 0.94 if word.isascii() else 0.60


def step(carry, prefix, upstream):
    return None, response(prefix.token_strings[-1])

