"""layers.1.mlp.down_proj:994, a weak component that reads the token stream.

Its activation is near zero for most text. It is large on a few kinds of token, and the
signs follow simple, human-readable contexts:

  * Row start (position 0, nothing before it): indentation made of two or more spaces is
    strongly positive; a single space slightly positive; other tokens slightly negative.
  * The token right after <|endoftext|>: negative.
  * Double-backslash tokens. Inside a string, as an escaped newline (after an escaped quote
    or an escaped "\\n") they are positive. After a digit or a closing bracket, as a LaTeX
    line break, they are negative. A LaTeX break written " \\\\" (space first) is negative
    after a digit or closer, and mildly positive otherwise.
  * A single space at the start of a line: negative, most strongly after an escaped "\\n"
    in a string (the space that follows a literal newline escape), less after a real
    newline.
  * Indentation of two or more spaces after an escaped "\\n", after a line ending in ":"
    (a block opener), or after a line ending in a space: mildly negative.

Everything else predicts 0. Values are rounded means over about 16k training rows
(position 0 and the escaped-newline cases are the largest). Single-token and
regression-free: a person can read every rule off the code.
"""

READS = ()

SPACES = " \t\xa0"
EOT = "<|endoftext|>"
BS2 = "\\\\"


def _spaces_only(s):
    """Spaces, non-breaking spaces or tabs only (no visible characters)."""
    return len(s) > 0 and all(c in SPACES for c in s)


def _escaped_newline(prev):
    return prev == "n" or prev.endswith("\\n")


def _after_code_or_math(prev):
    """A digit, or a closing bracket: the end of a LaTeX or code expression."""
    return len(prev) > 0 and (prev[-1].isdigit() or prev[-1] in ")}]")


def _in_string(prev):
    """A quote character, possibly escaped: the token sits inside a string literal."""
    return prev.endswith('"') or prev.endswith('\\"')


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if prefix.position == 0:
        if _spaces_only(tok) and "\t" not in tok:
            return carry, (3.1 if len(tok) >= 2 else 0.15)
        return carry, -0.17
    prev = prefix.token_strings[-2]
    if prev == EOT:
        return carry, -0.25
    if tok == BS2:
        if _after_code_or_math(prev):
            return carry, -1.1
        if _in_string(prev):
            return carry, 1.5
        if _escaped_newline(prev):
            return carry, 1.0
        return carry, 0.7
    if tok == " " + BS2:
        return carry, -1.8 if _after_code_or_math(prev) else 0.5
    if "\\\\" in tok:
        return carry, 0.5
    if tok == " " and _escaped_newline(prev):
        return carry, -0.8
    if tok == " " and (prev.endswith("\n")):
        return carry, -0.27
    if _spaces_only(tok) and "\t" not in tok and len(tok) >= 2:
        if _escaped_newline(prev):
            return carry, -0.26
        if prev.endswith(":\n") or prev.endswith(":"):
            return carry, -0.15
        if prev.endswith(" \n") or prev.endswith("  \n"):
            return carry, -0.16
    return carry, 0.0

