    if number.count('.') > 1:
        number = ''
    if number.endswith(('.', ',')):
        number = ''
    digits = sum(c.isdigit() for c in number)
    recent = text[-64:]
    density = sum(c.isdigit() for c in recent) / max(1, len(recent))
    strength = 0.0
    if digits:
        if '.' in number or ',' in number or "'" in number:
            strength = 2.6 + 2.3 * density + 0.15 * min(digits, 8)
            if '.' in number and ',' in number:
                strength += 1.5
        else:
            strength = (0.2 + 2.0 * density) * min(1.0, digits / 2)
    if padding >= 4 and any(c.isdigit() for c in text[-32:]):
        strength = max(strength, min(3.5, 0.22 * padding))

    horizontal = bool(s) and all(c in ' \t\u00a0' for c in s)
    pipe = '|' in s and not any(c.isalnum() for c in s)
    amp = s.startswith(' ') and s.strip() == '&'
