    if head and word:
        if family == 'LATIN':
            if n == 1:
                current_vowel, previous_vowel = vowel(head[0]), vowel(word[-1])
                if m <= 3:
                    if current_vowel:
                        value = -0.34 if previous_vowel else -0.52
                    else:
                        value = -0.49 if previous_vowel else -0.20
                else:
                    value = -0.28 if current_vowel else (
                        -0.32 if previous_vowel else -0.14)
            elif n == 2:
                value = -0.20 if m <= 3 else -0.08
            elif n == 3:
                consonant_cluster = not any(vowel(c) for c in word)
                value = -0.07 if m <= 2 or consonant_cluster else 0.01
            else:
                value = 0.024
        elif family == 'CYRILLIC':
            value = (-0.65, -0.26, -0.025)[n-1] if n <= 3 else 0.006
        elif family == 'ARABIC':
            value = (-0.48, -0.22, -0.30)[n-1] if n <= 3 else 0.006
        elif family == 'GREEK':
            value = -0.50 if n == 1 else -0.28 if n == 2 else 0.006
        elif family == 'KATAKANA':
            value = -0.50 if n == 1 else -0.12 if n == 2 else 0.006
    if first:
        value = -0.06 if text.startswith('<|') else -0.34
    if head == text and word:
        word = (word + text)[-64:]
    else:
        word = tail_match[0] if tail_match else ''
    return (doc, word), value

programs.haiku:
"""Layer-1 MLP neuron 996 (down_proj component): "spelling out an unrecognised word".

The component goes negative while the model is reading a word it has not yet recognised,
i.e. a word whose letters so far are only one or two characters long, and it is pushed
down by the next word-building piece (letters glued onto the word, no leading space).

Rules, in order:
- a run of middle dots "··" (filler) gives a large negative value;
- the first token of a document (no context yet) gives a moderate negative value;
- a word-building piece (letters, no leading space) after a word whose letters so far are
  1 letter gives -0.4, after 2 letters -0.14, after 3 letters -0.04, later about 0;
  Cyrillic, Greek and Arabic pieces count 1.5 times as strongly; CJK, Hangul and kana,
  which are not spelled out in letters, count zero;
- anything else is 0.
"""
READS = ()

# scripts written without letter-by-letter spelling (CJK ideographs, kana, Hangul)
NOT_LETTER_SCRIPT = ((0x3040, 0x30FF), (0x3400, 0x9FFF), (0xAC00, 0xD7AF), (0xF900, 0xFAFF))
# scripts where the effect is stronger (Cyrillic, Greek, Arabic)
WIDE_SCRIPT = ((0x0370, 0x03FF), (0x0400, 0x04FF), (0x0600, 0x06FF))


def _in(s, ranges):
    return any(lo <= ord(ch) <= hi for ch in s for lo, hi in ranges)


def step(carry, prefix, upstream):
    # carry: number of letters in the current word so far (0 if none)
    s = prefix.token_strings[-1]
    new_doc = len(prefix) == 1 or prefix.document_ids[-2] != prefix.document_ids[-1]
    letters = 0 if (carry is None or new_doc) else carry
    if s == "··":
        return 0, -2.3
    value = -0.34 if new_doc else 0.0
    if s.isalpha() and letters > 0 and not new_doc:
        # a word-building piece glued onto the word so far
        if not _in(s, NOT_LETTER_SCRIPT):
            base = {1: -0.4, 2: -0.14, 3: -0.04}.get(letters, 0.0)
            value = base * (1.5 if _in(s, WIDE_SCRIPT) else 1.0)
        letters += len(s)
    elif s.strip().isalpha():
        # a new word (leading space, or after punctuation)
        letters = len(s.strip())
    else:
        letters = 0
    return letters, value

programs.sol:
"""Source setup declarations, with a few document-format signals.

Nearby Python-shaped imports amplify the response; Java/JS/Go cues lower it.
Indented or escaped code is weaker. Document-initial keywords are suppressed.
C standard-library headers
amplify subsequent includes. Smaller rules cover aliases and forum labels;
middle-dot filler has a negative response. Unrecognized positions return zero.
The trailing text buffer resets at document boundaries.
"""
import re

READS = ()
C_HEADERS = frozenset('''
    assert ctype errno fenv float inttypes iso646 limits locale math setjmp
    signal stdalign stdarg stdatomic stdbool stddef stdint stdio stdlib
    stdnoreturn string tgmath threads time uchar wchar wctype
'''.split())
PY_DECL = re.compile(
    r'(?m)^[ \t+\d]*(?:from[ \t]+[\w.]+[ \t]+import[ \t]+[\w., *]+'
    r'|import[ \t]+[\w., ]+)[ \t]*(?:#.*?)?$')
SIGNALS = {'import', 'from', 'as', '#include', 'include', '<', '"', '#define',
           'Posts', 'views', 'Asked', 'Question', 'ed', 'Views', 'Related',
           'Posted', 'Ratings', 'asked'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    value = 0.0
    if len(word) >= 2 and set(word) == {'·'}:
        value = -1.8
    elif word in SIGNALS:
        recent = text.replace('\\n', '\n').replace('\\t', '\t').replace('\r', '')
        line = recent.rsplit('\n', 1)[-1]
        leading = not line.strip(' \t+->0123456789#`')
        if word in {'import', 'from'}:
            # Count the nearby, uninterrupted block of import declarations.
            count, comment_factor = 0, 1.0
            for old in reversed(recent[-350:].split('\n')[:-1]):
                if not old.strip() or old.lstrip().startswith('#'):
                    continue
                if re.fullmatch(r'[ \t]*(?:try:|except\b.*:|else:)', old):
                    continue
                if PY_DECL.fullmatch(old):
                    count += 1
                    if count == 1 and '#' in old:
                        comment_factor = 0.2
                elif count == 0 and re.fullmatch(r'[ \t]*[\w.]+\s+as\s+\w+', old):
                    count += 1  # A row may start partway through an import.
                else:
                    break
            python = bool(re.search(
                r'python|\.py\b|(?:^|\n)[ \t]*(?:def |class |#!)'
                r'|"""|\x27\x27\x27', recent, re.I))
            bare = token == word
            escaped = '\\n' in text[-80:]
            if word == 'import' and (bare or leading or token.startswith('\t')):
                java = re.search(
                    r'package\s+[\w.]+;|import\s+[\w.*]+;|\b[Jj]ava\b'
                    r'|[\w.]+;\s*$', recent)
                go = re.search(r'(?m)^[ \t]*package[ \t]+\w+|\.go\b', recent)
                js = re.search(
                    r'''javascript|typescript|\.[jt]sx?\b|import[^\n]*\bfrom[ \t]*['"]'''
                    r'''|import[ \t]*['"{*]|```(?:js|jsx|tsx|dart)\b''', recent)
                if java:
                    value = -0.1
                elif go and not count:
                    value = 0.6
                elif js and not count:
                    value = 0.2
                else:
                    repeats = comment_factor * (
                        8.2 * bool(count) + 1.6 * min(2, max(0, count - 1)) * bare)
                    value = 5.3 + repeats + 0.8 * python
                    value *= (1.0 if bare else 0.55) * (0.7 if escaped else 1.0)
                    if not leading:
                        value *= 0.15 if ';' not in line else 0.6
                    if not text:
                        value = -2.1 if bare else -0.1
            elif word == 'import' and line.strip().endswith(('import', 'open')):
                value = 7.0
            elif word == 'from' and (bare or leading or token.startswith('\t')):
                value = 0.4 + 3.5 * bool(count) + 0.9 * python
                value *= (0.5 if token.startswith('\t') else 1) * (0.5 if escaped else 1)
                if not text:
                    value = -0.3
        elif token == ' as':
            if re.search(r'^[ \t+\d]*(?:from\b.*\bimport|import)\b', line):
                value = 1.0
            elif re.search(r'^[ \t+\d]*(?:with|except)\b', line):
                value = 0.8
        elif word == '#include' or (word == 'include' and text.endswith('#')):
            headers = re.findall(r'#\s*include\s*[<"](\w+)\.h[>"]', recent[-350:])
            value = 2.2 + 2.1 * ('#include' in recent)
            value += 2.1 * any(h in C_HEADERS for h in headers)
            if not leading:
                value *= 0.6
            if not text:
                value = -1.1
        elif word in {'<', '"'} and re.search(r'#\s*include\s*$', recent):
            value = 1.6
        elif word == '#define':
            value = 0.7
        elif word == 'Posts':
            if leading:
                value = 0.9 + 3.6 * ('Joined:' in recent[-250:])
            elif line.strip().endswith('Recommended'):
                value = 1.4
        elif word == 'views' and re.search(r'\d[kmKM]?$', text):
            value = 0.8
        elif word in {'Asked', 'Question'} and leading:
            value = 0.5 if word == 'Asked' else 0.2
        elif word in {'Views', 'Related', 'Posted', 'Ratings'} and leading:
            value = 1.6
        elif word == 'asked' and line.strip() == '•':
            value = 5.3
        elif word == 'ed':
            if text.endswith(('Download', 'download')):
                value = 1.4
            elif text.endswith(('Comment', 'View')):
                value = 0.9
    return (doc, (text + token)[-1800:]), float(value)

"""A detector for 发/發 and its Japanese and Korean counterparts.

Isolated characters have a large negative response; multi-character words
usually weaken it.  Common hair-length and research contexts weaken it too;
traditional 出發 (departure) strengthens it.  Development compounds
(開発 / 개발) are weaker.  Vietnamese phát also responds.  Separate small rules cover Japanese
収 and a syllable ending after Latin ph.  Document starts have a small
positive offset.  UTF-8 is accumulated until a whole character is available,
resetting at each document boundary.
"""
import codecs

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pending, previous = b'', ''
    else:
        _, pending, previous = carry
    raw = prefix.token_bytes[-1]
    data = pending + raw
    text, used = codecs.utf_8_decode(data, 'ignore', False)
    word = text.strip()
    value = 0.0
    start = carry is None or carry[0] != doc
    if len(prefix.token_ids) > 1:
        start = start or prefix.token_strings[-2] == '<|endoftext|>'
    if start and not word.startswith('<|'):
        value = 0.23 if word[:1].isalpha() else 0.12

    if word == '发':
        if previous.endswith(('长', '短')):  # Long or short hair.
            value = -3.3
        elif previous.endswith(('开', '開')):
            value = -1.2
        else:
            value = -4.3 if raw.startswith(b' ') else -5.2
    elif word == '發':
        if previous.endswith('研'):  # Research and development.
            value = -3.9
        elif previous.endswith('出'):  # Departure.
            value = -10.3
        else:
            value = -6.3
    elif word == '発':
        value = -6.8 if previous.endswith('開') else -12.0
    elif word in ('髮', '髪'):
        value = -5.0 if word == '髮' else -8.0
    elif word == '발':
        value = -1.7 if previous.endswith('개') else -6.3
    elif word.lower() == 'phát':
        value = -7.9
    elif word == '収':
        value = -2.1
    elif '发' in word or '發' in word:
        if word in ('开发', '開發'):
            value = -0.8
        elif word == '研发':
            value = -2.1
        elif word == '沙发':  # A borrowed word meaning sofa, not emission.
            value = 0.0
        elif len(word) == 2 and word.endswith(('发', '發')):
            value = -3.5
        elif len(word) == 2:
            value = -0.4
        else:
            value = -0.15
    elif word in ('at', 'át', 'ôt', 'ạt', 'ất'):
        if previous.lower().endswith('ph'):
            value = -3.0

    previous = (previous + text)[-12:]
    return (doc, data[used:], previous), value

programs.haiku:
"""Indentation at the start of a line (layers.1.mlp.down_proj:999).

The component fires on a whitespace-only token that opens a new line: the indentation run
right after a newline. Its size depends on how that indent compares with the last
non-blank line above it:

- the indent is at least as deep as that line (a new block or a continuation):
  it fires, about 1.0 at an even width (2, 4, 8 spaces) and about 0.3 at an odd one;
- the indent is shallower than that line: it fires weakly (0.3) at an even width and
  stays silent at an odd one. Odd widths are where the tokenizer has left one space
  for the next word, so they mark a dedent.

Everything else (words, punctuation, digits, the first token of a document) predicts 0.
The program tracks the indent of the last non-blank line in its carry, and resets it at
a document boundary.
"""

READS = ()

NO_LINE = -1


def _advance(state, token):
    """Feed one token's characters through the line tracker.
    state = (indent of last non-blank line, indent so far of this line,
             this line has text yet, still in its leading whitespace)."""
    last, lead, text, in_lead = state
    for ch in token:
        if ch == "\n":
            if text:
                last = lead
            lead, text, in_lead = 0, False, True
        elif in_lead and ch in " \t\xa0":
            lead += 1
        else:
            in_lead = False
            text = True
    return (last, lead, text, in_lead)


def step(carry, prefix, upstream):
    if carry is None or prefix.document_ids[-1] != prefix.document_ids[-2]:
        state = (NO_LINE, 0, False, True)
    else:
        state = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if prefix.position > 0 and token.isspace() and "\n" in prefix.token_strings[-2]:
        width = len(token)
        deeper = width >= state[0]
        if width % 2 == 0:
            value = 1.0 if deeper else 0.3
        else:
            value = 0.3 if deeper else 0.0
    return _advance(state, token), value

programs.sol:
"""Responses to small round symbols, numeric zero fragments and indentation.

Degree signs depend strongly on the preceding digit: a final zero usually
suppresses them. Zero glyphs split across UTF-8 tokens can be much stronger.
ASCII zero has a small response increasing with the preceding digit.
Repeated middle dots and an initial line-comment opener have separate
responses; a bracketed en dash recognizes a Reddit comment marker.
Spaces immediately after line breaks are positive.
"""
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous = b'', ''
        first = True
    else:
        _, tail, previous = carry
        first = False
    raw = prefix.token_bytes[-1]
    token = prefix.token_strings[-1]
    joined = tail + raw
    value = 0.001

    if token.strip() == '°':
        last = previous[-1:]
        if last == '0':
            value = -0.04
        elif last == '1':
            value = 0.35
        elif last == '3':
            value = 0.26
        elif last.isdigit():
            value = 0.06
        elif last and unicodedata.category(last).startswith('P'):
            value = 1.8
        else:
            value = 0.8
    elif token == '–' and previous.endswith('['):
        value = 0.5
    elif token == '0':
        last = previous[-1:]
        value = 0.03
        if last and last in '0123456789':
            value = min(0.12, 0.018 * int(last) - 0.015)
    elif token == '··':
        value = -1.05 if previous == token or first else -0.12
    elif first and token == '//\n':
        value = 4.44
    elif token == ' ':
        if tail.endswith(b'\\n'):
            value = 0.4
        elif previous.endswith('\n'):
            value = 0.18
    elif len(raw) == 1 and 128 <= raw[0] < 192:
        char = joined.decode('utf-8', 'replace')[-1]
        if unicodedata.numeric(char, -1) == 0:
            value = 3.0 if char.isdecimal() else 2.2
        elif unicodedata.category(char) == 'Zs':
            value = 0.18
        elif char == '\uf0b0':  # Symbol-font degree sign in extracted documents
            value = 1.1

    return (doc, joined[-3:], token), value

programs.haiku:
"""Layer 1 MLP down-projection, component 1000: a weak, mostly token-level feature.

Almost all of its activation is small noise (std about 0.05) that no short rule
predicts. The rules below capture the few regularities that exist, as group averages:
- the first token of a packed row: about -0.08 (its value depends only on the token);
- the bare digit 0 and a lone space token: slightly positive (about +0.03 and +0.014);
- Unicode replacement characters (pieces of multi-byte text split across tokens) and
  the degree sign: slightly positive (about +0.02 and +0.025);
- a hash sign '#': slightly negative (about -0.03);
- special chat-template tokens such as <|im_start|>: about +0.03.
Everything else predicts 0.
"""

READS = ()

ZERO_TOKEN = 0.028
SPACE_TOKEN = 0.014
REPLACEMENT = 0.019
DEGREE = 0.025
HASH = -0.027
SPECIAL = 0.026
ROW_START = -0.077


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if prefix.position == 0:
        return carry, ROW_START
    if tok == "0":
        return carry, ZERO_TOKEN
    if tok == " ":
        return carry, SPACE_TOKEN
    if "�" in tok:
        return carry, REPLACEMENT
    if "°" in tok:
        return carry, DEGREE
    if "#" in tok:
        return carry, HASH
    if tok.startswith("<|"):
        return carry, SPECIAL
    return carry, 0.0

programs.sol:
"""Approximate the component's document-opening lexical response.

Bare declaration keywords give positive pulses, whereas literal backslash
newline/tab escapes give negative ones. Other opening tokens get a small
baseline by script, case and English function-word class. Apart from a
leading run of escapes, later tokens get the background mean; their
small lexical variation is omitted.
"""
import regex

READS = ()

# Each class has a bare-token and a space-prefixed opening response.
FUNCTION_WORDS = (
    (set('a an the'.split()), 0.38, 0.61),
    (set('i me my mine we us our ours you your yours he him his '
         'she her hers it its they them their theirs'.split()), -0.17, 0.18),
    (set('of in on at to from with by for about into over under '
         'after before between through without within'.split()), -0.16, 0.26),
    (set('and or but nor so yet because if when while although '
         'unless since as than'.split()), -0.01, 0.22),
    (set('am is are was were be been being'.split()), -0.35, 0.35),
)
SCRIPTS = (
    ('Thai', -0.9), ('Cyrillic', -0.25), ('Greek', -0.45),
    ('Arabic', -0.34), ('Hangul', -0.32), ('Katakana', -0.5),
    ('Han', 0.11),
)
SCRIPT_RULES = [(regex.compile(r'\p{Script=' + s + '}'), v)
                for s, v in SCRIPTS]


def opening_value(text):
    if text in {'int', 'uint', 'bool', 'void', 'unsigned'}:
        return 2.25
    if text in {'const', 'class', 'struct', 'var', 'let',
                'static', 'public', 'private'}:
        return 1.5
    if text in {'char', 'string', 'String'}:
        return 1.3
    if text in {'short', 'long', 'float', 'double', 'byte'}:
        return 0.6
    if text in {'import', 'def'}:
        return 0.7
    if text.startswith('<|'):
        return -0.20
    word = text.strip()
    if not word:
        return 0.03
    if word.isascii() and word.isalpha():
        spaced = text.startswith(' ')
        for words, bare, after_space in FUNCTION_WORDS:
            if word.lower() in words:
                return after_space if spaced else bare
        if spaced:
            return 0.22 if word.islower() else 0.03
        if word.isupper():
            return -0.25 if len(word) > 2 else -0.03
        return 0.22 if word.istitle() else 0.10
    for pattern, value in SCRIPT_RULES:
        if pattern.match(word):
            return value
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    text = prefix.token_strings[-1]
    escaped_space = text in {'\\n', '\\t'}
    escape_run = (first or carry[1]) and escaped_space
    if escape_run:
        value = -1.85
    else:
        value = opening_value(text) if first else -0.001
    return (doc, escape_run), value

"""Second-person address: pronouns, possessives and some verb endings.

The strongest negative responses name the listener (you, tu, du, 你 ...).
Short ambiguous pieces are gated by the surrounding language. English
questions/conditionals are weaker than object uses. Recognizable second-person
word endings are included when a word is split across tokens. English you/your
have a positive exception at the first token of a document. Unrecognized text
is zero. State retains only 250 recent characters and resets per document.
This is a linguistic approximation; lexical spillovers are not modeled.
"""
import re

READS = ()

# Function words provide a small, explicit language detector.
LANGUAGE_WORDS = {
    'en': 'the and of is are that this with for from not be have it you your',
    'fr': 'le la les des du une et est je ne pas pour que qui ce dans vous nous',
    'es': 'el los las del una y es para por que no se con lo como pero muy',
    'it': 'il gli della di che e non per sono si con nel alla anche come',
    'de': 'der die das den dem ein eine und ist nicht ich mit für auf zu von wir',
    'nl': 'het een van voor met zijn niet dat op je als deze wordt ook maar',
    'sv': 'och att är det som på har om jag inte till men den',
}
LANGUAGE_WORDS = {k: set(v.split()) for k, v in LANGUAGE_WORDS.items()}

# Unambiguous second-person words, including possessive and reflexive forms.
PRONOUNS = {
    'yourself': -0.9, 'yourselves': -0.9, 'yours': -1.2,
    'thou': -4.2, 'thee': -4.3, 'thy': -4.3, 'thine': -4.5,
    'vous': -2.7, 'votre': -1.6, 'vos': -2.7, 'toi': -8.0,
    'tú': -5.0, 'usted': -1.7, 'ustedes': -1.7,
    'ты': -6.0, 'тебя': -5.0, 'тебе': -5.0, 'вы': -2.1,
    'вас': -1.8, 'вам': -1.6,
    'você': -1.0, 'vocês': -1.0, 'euch': -5.0,
}


def language(text):
    words = re.findall(r'[^\W\d_]+', text.lower())[-35:]
    scores = {k: sum(w in cues for w in words)
              for k, cues in LANGUAGE_WORDS.items()}
    return max(scores, key=scores.get) if max(scores.values()) >= 2 else 'en'


def predict(text, token, first):
    raw = token.strip()
    lower = raw.lower()
    previous = re.findall(r'[^\W\d_]+', text)[-1:]
    prev = previous[0] if previous else ''
    joined = re.search(r'[^\W\d_]+$', text + token)
    word = joined[0].lower() if joined else ''
    whole = lower == word

    if lower in ('you', 'your') and whole:
        if first:
            value = (1.96 if lower == 'you' else 2.24)
            value += 1.2 if raw[:1].isupper() else 0.0
            if token[:1] == ' ' and raw[:1].isupper():
                value += 0.9
            return value
        if lower == 'your':
            return -0.85 if raw[:1].isupper() else -1.15
        if raw[:1].isupper():
            return -1.25 if token.startswith(' ') else -1.0
        if prev.lower() == 'thank':
            return -0.35
        if prev in ('Do', 'Are'):
            return 0.1
        if prev.lower() in ('if', 'when', 'where', 'how', 'so', 'can',
                            'could', 'would', 'do', 'did', 'or'):
            return -0.65
        if prev.lower() in ('to', 'for', 'as', 'help', 'give', 'gives',
                            'provide', 'assist', 'allow', 'allows', 'get'):
            return -2.0
        return -1.1
    if whole and lower in PRONOUNS:
        return PRONOUNS[lower]
    if '你' in token or '妳' in token:
        return -2.2
    if '您' in token:
        return 0.74 if first else -1.0
    if word == 'ты' and lower == 'ы':
        return -8.0
    if word.startswith('тво') and lower in ('во', 'вой', 'воя', 'вои'):
        return -9.0
    if re.fullmatch(r'dein(?:e[rmns]?)?|eure?[mnr]?|de', word):
        if language(text) == 'de':
            return -3.0 if word == 'de' else -7.0
    if whole and lower in ('du', 'dir', 'dich'):
        if language(text) in ('de', 'sv'):
            return -7.0
        return -0.1
    if whole and lower in ('tu', 'te', 'ti', 'tus', 'tua', 'tuo', 'tue',
                            'ton', 'tes', 'ta', 't', 'hai'):
        lang = language(text)
        if lang in ('fr', 'es', 'it'):
            if lower == 't':
                return -5.0 if lang == 'fr' else -0.2
            if lower in ('ton', 'tes', 'ta'):
                return -5.0 if lang == 'fr' else -0.1
            if lower == 'hai' and lang != 'it':
                return -0.1
            return -7.5
        return -0.1
    if whole and lower == 'je' and language(text) == 'nl':
        return -1.2
    # The distinctive final piece of an inflected second-person word.
    if not whole and word != lower:
        if lower in ('arte', 'erte', 'irte', 'arti', 'erti', 'irti'):
            if language(text) in ('es', 'it'):
                return -6.0
        if lower in ('as', 'es', 'ás', 'és'):
            if word in ('puedes', 'puedas', 'quieres', 'tienes', 'tengas',
                        'crees', 'eres', 'usas', 'hayas', 'mencionas', 'estás'):
                return -7.0
            if lower in ('ás', 'és') and language(text) == 'es':
                return -6.0
        if word in ('stai', 'sai', 'hai', 'puoi', 'voi'):
            return -6.0
        if word == 'thine':
            return -4.5
    if lower in ('ك', 'لك', 'تك'):
        return -4.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    text = '' if first else carry[1]
    token = prefix.token_strings[-1]
    value = predict(text, token, first)
    return (doc, (text + token)[-250:]), value

programs.haiku:
"""Second-person address: the component goes negative on words that address the reader.

It is a "you" detector in any language. It reads the token as written, with its leading
space: a word-initial " tu" or " te" is a pronoun, while a mid-word "tu" is a fragment and
is ignored. Informal singular forms are the most negative: French tu, German dich, dein, Du,
archaic thou, thy and thee, Spanish tienes-type verb forms, Russian ты. Polite and plural
forms are medium: vous, вы, 你, Arabic ك, Italian ti. English you, your and yourself are weak,
and so are German du and dir, which often are not pronouns. English "you" is weaker after
"if", "when", "do", "how" or "Thank" and stronger after a verb or preposition ("give you",
"to you"). Everything else predicts 0.
"""

READS = ()

STRONG = {
    " tu", " tus", " tua", " ti", " toi", " dich", " dein", " deine", " euch",
    " thou", " Thou", " thy", " Thy", " thee", " tienes", " puedes", " quieres", " bist",
    " ты", " тебя", " тебе", " لك", " تك", "ешь",
}
MEDIUM = {
    " te", " vous", " Vous", " vos", " votre", " hast", " vosotros",
    " вы", " Вы", " вас", " вам", " ваш", " ваши", "你", "你的", "妳", "ك",
}
WEAK = {
    " du", " Du", " dir", " Dir", " Te", "Te", " ton", " você", " usted", " 您", "您", " 你们",
    "你们",
}
ENGLISH = {" you", " your", " You", " Your", " yours", " yourself", " YOUR", " yourselves"}
AFTER_SUBJECT = {"if", "If", "when", "When", "do", "Do", "how", "How", "Thank", "thank", "can", "Can"}
AFTER_OBJECT = {
    "give", "gave", "to", "help", "for", "with", "as", "tell", "told", "ask", "from", "in", "on",
    "at", "of", "about", "bring", "show", "let", "send", "offer",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    before = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    if word in STRONG:
        value = -5.0
    elif word in MEDIUM:
        value = -2.5
    elif word in WEAK:
        value = -1.5
    elif word in ENGLISH:
        value = -1.1
        if before in AFTER_SUBJECT:
            value = -0.5
        elif before in AFTER_OBJECT:
            value = -1.5
    else:
        value = 0.0
    return carry, value

programs.sol:
"""A sparse detector of metadata boundaries and a few fixed phrases.

Colons after forum/profile and mail headings are positive, especially Joined.
Re: is stronger after a Kudos reputation marker; Title: is strong only at the
opening of a document. Underscores in anonymized names are negative. Smaller
rules cover LaTeX closers, Python's initializer argument, greetings and idioms,
and two GitHub corpus tags. Unrecognized positions return zero. State is just
the document position and whether a Kudos marker has occurred.
"""
import re

READS = ()

# Field names, not token IDs. Values are fitted boundary-response strengths.
FIELD_COLONS = {
    'Topic': 3.6, 'Forum': 2.3, 'Posted': 3.3, 'Kudos': 2.3,
    'Subject': 1.4, 'From': 1.4, 'Posts': 1.1, 'Location': 0.9,
    'Status': 1.4, 'Updated': 1.0, 'Filed': 1.2, 'Edited': 1.2,
    'Given': 1.5, 'given': 1.5, 'Replies': 1.4, 'Views': 0.8,
    'Input': 0.6, 'Answered': 2.3, 'Concentration': 1.1,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, reputation = 0, False
    else:
        position, reputation = carry[1] + 1, carry[2]
    tokens = prefix.token_strings[-min(position + 1, 4):]
    t = tokens[-1]
    previous = tokens[-2] if position else ''
    before = ''.join(tokens[:-1])
    recent = before + t
    reputation = reputation or recent.endswith('Kudos')
    value = 0.0

    if t == ':':
        match = re.search(r'[A-Za-z-]+$', before)
        label = match.group() if match else ''
        if label == 'Joined':
            value = 11.8 if previous == label else 9.8
        elif label in ('Re', 'RE'):
            value = (7.5 if reputation else 4.4) if previous == label else 3.6
        elif label == 'Title' and position == 1:
            value = 8.5
        elif label == 'To':
            value = 4.2
        else:
            value = FIELD_COLONS.get(label, 0.0)
            if previous.startswith(' ') and label in ('Posts', 'Location'):
                value = 0.4 if label == 'Posts' else 0.2
    elif t == '_':
        if previous.strip() == 'NAME':
            value = -2.3 if previous.startswith(' ') else -1.6
        elif previous.strip() == 'username':
            value = -9.3
        elif previous == ' u':  # Lean universe variables such as u_1
            value = -0.8
    elif t == ']' and before.lower().endswith('solved'):
        value = 6.5 if before.endswith('SOLVED') else 1.9
    elif t in (')', ']') and previous.endswith('\\'):
        value = 1.1  # closing a LaTeX math delimiter
    elif t in ('\\)', '\\]'):
        value = 1.0
    elif t == 'self' and previous == '__(':
        value = 0.7
    elif t == ' there' and previous.strip() in ('Hi', 'Hey'):
        value = -3.6 if previous.strip() == 'Hi' else -6.0
    elif t in (' one', ' ones') and previous == ' loved':
        value = -3.2
    elif t == ' you' and previous.strip().lower() in ('thank', 'mind'):
        value = -3.0 if previous.strip().lower() == 'mind' else -0.7
    elif t == 'ly' and previous.strip() == 'Related':
        value = 2.0
    elif t == 'ars' and recent.endswith('<gh_stars'):
        value = -5.2
    elif t == 'ame' and recent.endswith('<reponame'):
        value = -6.0
    elif t == 'Joined':
        value = 0.7
    return (doc, position, reputation), value

"""An uncontracted 'be' auxiliary detector, with short grammatical context.

The largest outputs are for be/been/being. A preceding modal, an infinitive
construction, or a personal/existential subject changes their strength.
Finite forms are weaker, especially after human pronouns. Small rules also
cover contractions, negation, auxiliary + then, become, and some foreign
auxiliaries and case particles. Everything else gets zero. Only the current
token and two previous tokens are used, resetting at document boundaries;
small unrelated lexical responses are deliberately left unexplained.
"""
READS = ()

FINITE = {'is', 'are', 'was', 'were'}
PERSONAL = {'i', 'you', 'we', 'he', 'she'}
DEICTIC = {'this', 'these', 'those'}
MODALS = {
    'can': 3.2, 'cannot': 2.9, 'could': 2.15, 'should': 2.2,
    'must': 2.05, 'shall': 2.65, 'will': 1.85, 'would': 1.5,
    'may': 1.9, 'might': 1.4,
}
SEEMING = {'seem', 'seems', 'seemed', 'appear', 'appears', 'appeared'}
PASSIVE_AUXILIARIES = {
    'être': 2.6, 'été': 2.1, 'werden': 0.85, 'wird': 0.85,
    'wurde': 1.0, 'быть': 1.6, 'был': 1.0, 'будет': 0.7,
    'ser': 1.05, 'fut': 1.0, 'foi': 1.5, 'são': 1.0,
}
COPULAS = {'est', 'sont', 'è', 'sono', 'jest'}


def finite_value(word, prev):
    """Copulas after human, deictic, relative, and ordinary noun subjects."""
    p = prev.strip().lower()
    past = word in {'was', 'were'}
    value = {'is': 0.68, 'are': 0.85, 'was': 1.0, 'were': 1.4}[word]
    if p in PERSONAL or p == 'who':
        value = (0.32 if word == 'was' else 0.15) if past else 0.02
        if not past and p in {'we', 'you'}:
            value = -0.3
    elif p == 'there':
        value = {'is': 0.06, 'are': -0.08, 'was': 0.24, 'were': 0.1}[word]
    elif p == 'it' or p == 'they':
        value = 0.8 if past else (0.52 if p == 'it' else 0.37)
        if prev.strip()[:1].isupper():
            value -= 0.17
    elif p in DEICTIC:
        value = 0.55 if past else (0.24 if p == 'this' else 0.4)
    elif p in {'which', 'that'}:
        value = 0.92 if past else (0.46 if word == 'is' else 0.62)
    elif p in {'here', 'what'}:
        value = 0.7 if past else 0.08
    elif p in {'and', 'or', 'but', ','}:
        value *= 0.55
    elif prev.strip()[:1].isupper():
        value -= 0.25
    return value if prev else -0.4


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev, before = '', ''
    else:
        _, prev, before = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    p, b = prev.strip().lower(), before.strip().lower()
    value = 0.0
    if token == ' be':
        value = MODALS.get(p, 1.8)
        if p == 'to':
            if b in FINITE:
                value = 3.1
            elif b in {'need', 'needs', 'needed', 'has', 'had'}:
                value = 2.8
            elif b == 'have':
                value = 2.2
            elif b in SEEMING or b == 'want':
                value = 0.85
            elif b in {'going', 'supposed', 'expected', 'likely', 'meant'}:
                value = 1.3
        elif p in {'not', 'also', 'only', 'never'}:
            value = MODALS.get(b, 1.8) * 0.8 + 0.65
        elif p in {'and', ',', ')'}:
            value = 1.2
    elif token == ' been':
        value = {'has': 2.4, 'have': 2.05, 'had': 1.9,
                 'not': 3.0, 'also': 2.5}.get(p, 1.4)
        if b in PERSONAL or b == 'there' or p in {'always', "'ve"}:
            value = 0.8
    elif token == ' being':
        value = 3.7 if p in FINITE else 1.5
        if p in {'of', 'to', 'human', ','}:
            value = 0.85
        elif b in FINITE and p in {'not', 'now', 'just', 'still'}:
            value = 2.8
    elif token in {' is', ' are', ' was', ' were'}:
        value = finite_value(word, prev)
    elif token in {' Be', 'Be'}:
        value = 0.8
    elif token == ' then' and p in FINITE:
        value = 1.5
    elif token in {' not', 'not', ' Not', 'Not'}:
        value = 0.42 if p in FINITE else 0.22
        if p in {'do', 'does', 'did', 'could', 'may', 'might'}:
            value = 0.07
    elif token == ' am' or token == "'m":
        value = -0.17 if token == ' am' else -0.39
    elif token == "'re":
        value = -0.15 if p == 'they' else -0.4
    elif token.startswith(' ') and token.strip() == word:
        value = PASSIVE_AUXILIARIES.get(word, 0.0)
        if word in COPULAS:
            value = 0.65
        elif word in {'become', 'becomes', 'became', 'becoming'}:
            value = 0.5
    elif token in {'を', '을', '를'}:
        value = 0.78
    elif token in {'は', 'が', '是'}:
        value = 0.3
    elif token == '被':
        value = 0.5
    return (doc, token, prev), value

programs.haiku:
"""Forms of the verb 'to be' (be, been, being, is, are, was, were, plus French/Spanish/German
equivalents), scaled by the word just before them: a modal ("can be") or "have/has" ("has been")
makes the non-finite form fire much harder than "to be" or a finite form after a pronoun.
"""
READS = ()

BE_FORMS = {
    " be": 2.0, " been": 2.2, " being": 2.0,
    " is": 0.5, " are": 0.6, " was": 0.8, " were": 0.9,
    " être": 3.3, " est": 0.9, " sont": 1.0, " ser": 0.9, " são": 1.3, " foi": 1.7,
    " wird": 0.9, " werden": 0.9, " sind": 0.5, " sono": 0.8, " é": 0.4, " è": 0.7,
}
# What the word before "be" / "been" does to it (multiplier).
BEFORE_BE = {
    " can": 1.6, " cannot": 1.5, " shall": 1.5, " should": 1.2, " must": 1.1, " could": 1.15,
    " may": 1.0, " will": 0.9, " would": 0.85, " to": 0.9, " not": 1.05,
    " has": 1.1, " have": 1.0, " had": 0.95,
}
PRONOUN_BEFORE = {" it", " there", " this", " that", " he", " she", " I", " you", " we", " they",
                  " which", " There", " They", " We", " He", " She", " You", " It", " This", " What"}
FINITE = {" is", " are", " was", " were"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = BE_FORMS.get(token, 0.0)
    if len(prefix.token_strings) > 1:
        before = prefix.token_strings[-2]
        if token in (" be", " been", " being"):
            value *= BEFORE_BE.get(before, 1.0)
        if token in FINITE and before in PRONOUN_BEFORE:
            value *= 0.4
    return carry, float(value)

programs.sol:
"""Context-sensitive opening-markup pulses, usually negative.

Indented '<' is strong; comparisons and type parameters are mostly quiet.
Quoted, adjacent, and comment markup have smaller pulses. LaTeX environment
braces, ES-module keywords, and Persian beh/heh sequences are secondary cases.
Only a 512-character recent context and two previous tokens are retained.
"""
import re

READS = ()


def predict(s, prev, prev2, text, position):
    if s == ' به':
        return -4.5
    if s == 'ه' and prev.strip() in ('ک', 'ك', 'چ'):
        return -2.4
    if s == ';' and text.endswith('&lt'):
        return -4.5
    if not ('<' in s or s == '{' or s.strip() in ('import', 'export')):
        return 0.0

    line = re.split(r'\n|\\n', text)[-1]
    if s == '{':
        if prev2.endswith('\\') and prev in ('begin', 'end'):
            if prev == 'end':
                return -1.1
            if re.search(r'\$\\begin$', text):
                return -7.6
            return -5.8 if len(line) <= 11 else -4.1
        return 0.0

    js = bool(re.search(
        r'```(?:jsx?|tsx?|javascript|typescript)|className|=>|\b(?:const|let)\b',
        text))
    es_module = bool(re.search(r'\bimport[^;\n]*\bfrom\s+["\']', text))
    if s.strip() in ('import', 'export'):
        if position == 0:
            return 0.3
        if es_module:
            if s.strip() == 'export':
                return -2.0
            return -4.7 if len(line.strip()) <= 1 else -1.5
        if js:
            return -1.7 if not line.strip() else -0.7
        return 0.16

    if s == '<h' and not line.strip() and position:
        return -6.0
    if not (s.endswith('<') and s.count('<') == 1 and '|' not in s):
        return 0.0
    if '\\' in s and '>' not in s:
        return 0.0                 # Escaped mathematical less-than.
    if s == '::<':
        return 0.2                 # Rust type arguments, not markup.
    if re.search(r':[a-z]+:`[^`]*$', text):
        return -1.7                # reStructuredText cross-reference.
    if s == '<' and position == 0:
        return -0.4
    if s == '<' and re.search(r'(?m)^\d+(?:,\d+)?[acd]\d+', text):
        return 0.5                 # Traditional diff line marker.

    start = re.split(r'\n|\\n', text + s[:-1])[-1]
    if prev.isspace() and s == ' <':
        if re.match(r'^\s*(?:\*|///|//)', start):
            return -4.7
        return -13.0 if es_module else -9.2
    if prev.strip() in ('*', '///', '//'):
        return -2.7
    if not start.strip():
        explicit_xml = re.search(r'```(?:html|xml|jsx?|tsx?)|XML tags', text)
        return -9.0 if explicit_xml else -5.0
    if js and start.rstrip().endswith('return'):
        return -10.0
    if js and start.rstrip().endswith('='):
        return -5.0
    if s == '<' and start.rstrip().endswith(('"', "'", '`')):
        return -5.0
    if start.strip() in ('+', '-', '•', '✓', '✔'):
        return -8.0
    if s == '<' and prev.isspace() and '\t' in prev:
        return -4.5
    tags = len(re.findall(r'<[A-Za-z][^>]*>', text))
    if start.rstrip().endswith('>'):
        return -5.5 if tags else -3.0
    if any(c in s for c in '"\'`'):
        return -2.4
    if s == ' <' and tags >= 2:
        return -1.5
    return 0.2


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '', 0)
    _, text, prev, prev2, position = carry
    s = prefix.token_strings[-1]
    value = predict(s, prev, prev2, text, position)
    return (doc, (text + s)[-512:], s, prev, position + 1), value

"""Short f-containing fragments and negative relational constructions.

The positive rule recognizes a short word piece containing f (also Cyrillic
ф), especially the spelling uf or oof across a token boundary.  Negative
rules cover English time spans, Chinese support verbs and postpositions,
and Japanese/Korean relational particles.  Chinese verbs are identified
from dictionary meanings, not a memorized vocabulary of token IDs.
These are separate empirical cues, not a claim of one unified meaning.
Recent text is kept in an 80-character buffer, cleared between documents.
"""
import re
from functools import lru_cache
import regex
import cedict

READS = ()

MEANINGS = {
    'provision': r'to (?:provide|offer|supply|furnish)\b',
    'possession': r'to (?:have|possess)\b',
    'giving': r'to (?:give(?=$|[;,(])|give rise to|contribute|dedicate|'
              r'devote|create|produce|leave behind|bring|reserve|set aside)\b',
    'relation': r'to (?:obtain|acquire|receive|establish|arise|occur|exist|'
                r'carry out|conduct|generate|feel|show|express|indicate|'
                r'display|find|formulate)\b',
}
# Common Chinese light verbs: have, arise, do, hit/do, get, occupy.
LIGHT_VERBS = frozenset(('有', '起', '做', '打', '得', '占'))


@lru_cache(maxsize=12000)
def chinese_kind(word):
    if not regex.fullmatch(r'\p{Script=Han}+', word):
        return ''
    root = word.rstrip('了着') or word
    if root.endswith('有'):
        root = root.lstrip('也又还還')
    if root in LIGHT_VERBS:
        return 'light'
    if len(root) < 2:
        return ''
    # Use primary dictionary meanings, not rare secondary verbal readings.
    glosses = cedict.glosses(root)[:2]
    for kind, pattern in MEANINGS.items():
        if any(re.search(pattern, g) for g in glosses):
            return kind
    return ''


def f_piece(s, previous):
    piece = s.lower().replace('ф', 'f').replace('у', 'u')
    before = previous.lower().replace('у', 'u')
    if len(piece.strip()) > 4 or 'f' not in piece:
        return 0.0
    if piece.startswith(' '):
        return 1.3 if piece.strip().startswith('uf') else 0.0
    if not piece.isalpha():
        return 0.0
    if piece.startswith('uf') and (len(piece) <= 3 or piece.startswith('uff')):
        return 2.5
    if piece.startswith('f') and before.endswith(('u', 'oo')):
        return 3.6
    if piece.startswith('of') and before.endswith('o'):
        return 4.3
    if piece.startswith(('ef', 'iff')):
        return 0.3
    if piece.startswith('af'):
        return 0.3
    if piece.startswith('f') and before[-1:].isalpha():
        return 0.2
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        history, previous = '', ''
    else:
        _, history, previous = carry
    s = prefix.token_strings[-1]
    value = f_piece(s, previous)
    tail = history.lower()
    if s in (' past', ' last', ' next'):
        value = -0.45 if s == ' past' else 0.0
        span = re.search(r'\b(over|in|during|for|within|of|to) the$', tail)
        if span:
            preposition = span.group(1)
            if preposition == 'over':
                value = -7.0 if s == ' past' else -5.2
            elif s == ' past':
                value = -2.8
            elif preposition != 'of':
                value = -1.2
    if s == ' with' and re.search(
        r'\bprovid(?:e|es|ed|ing)(?:\s+\w+){0,3}$', tail
    ):
        value = -0.7

    kind = chinese_kind(s)
    dative = bool(re.search('[为為对對给給]', history[-16:]))
    locative = bool(re.search('[在于於向]', history[-16:]))
    aspect_marked = len(s) > 1 and s.endswith(('了', '着'))
    if kind == 'provision':
        value = -4.8 if dative else -0.7
    elif kind == 'giving':
        value = -0.25
        if dative:
            value = -4.0 if aspect_marked else -2.4
        elif aspect_marked and locative:
            value = -2.0
    elif kind == 'relation':
        value = -0.35 - (0.3 if dative else 0.5 if locative else 0.0)
        if aspect_marked:
            value -= 1.3
    elif kind == 'possession':
        value = -0.4
    elif kind == 'light':
        value = -0.45 - (0.3 if dative else 0.5 if locative else 0.0)
        if aspect_marked:
            value -= 1.5
    if s in ('了', '着'):
        value = -0.2 if s == '了' else -0.5
        if chinese_kind(previous):
            value -= 0.6 + (0.8 if dative or locative else 0.0)
    if s == '来说':
        value = -4.5 if dative else -0.5
    if s in ('上', '上的', '方面', '之间的'):
        value = -2.0 if s == '方面' and locative else -0.45
    if s == '的':
        value = -0.2 if dative else -0.05

    if s in ('に', 'にも', 'へ', 'での'):
        value = -0.35
    if s in ('にとって', 'に関する', 'への'):
        value = -1.8
    if s in ('において', 'について', 'に関して'):
        value = -0.8
    if s in ('에', '에는', '에도'):
        value = -0.7
    if s.strip() == '대한':
        value = -1.3

