            value = -0.22 if bare == 'it' else 0.15
        elif bare == 'It':
            value = 0.26
        elif recent.rstrip().endswith(','):
            value = 0.45
        elif previous in RELATIVES:
            value = 1.45 if previous in ('what', 'whatever') else 0.75
        elif 'make' in forms:
            value = 1.4 if previous == 'made' else 1.0
        elif forms & {'find', 'think'}:
            value = 0.68
        elif previous == 'have':
            value = 0.85
        elif previous in CONJUNCTIONS:
            value = 0.25
        elif previous in PREPOSITIONS:
            value = 0.24 if previous == 'for' else 0.07
        elif previous in ('that', 'is', 'does', 'has', 'was'):
            value = 0.58
        elif forms & {'use', 'add'}:
            value = -0.1
        else:
            value = 0.37
    elif bare in ('es', 'Es'):
        if boundary and (len(set(words[-30:]) & GERMAN) >= 2
                         or previous in {'ist', 'wird', 'hat', 'gibt', 'gab', 'sie'}):
            value = 1.65 if previous in ('gibt', 'gab') else 2.95
            if not token.startswith(' '):
                value *= 0.75
        else:
            value = 0.04
    elif bare in ('il', 'Il'):
        french = sum(w in FRENCH for w in words[-30:])
        italian = sum(w in ITALIAN for w in words[-30:])
        value = 1.0 if boundary and french > italian else 0.04
    elif token == "'il":
        value = 1.0
    elif bare in ('на', 'На') and boundary:
        value = 1.35 if bare == 'На' else 0.98
    elif bare in ('Det', 'det', 'het') and boundary:
        value = 0.65 if bare != 'het' else 1.0
    elif token == '··':
        value = -1.3
    elif token == ' its':
        value = 0.13
    elif token == ' them':
        value = -0.16
    elif token in (' -', ' --', ' /'):
        # Match an adjacent command, not a word before intervening code.
        match = re.search(r'[\w.+-]+$', recent)
        command = match.group() if match else ''
        line = recent.replace('\\\n', '').rsplit('\n', 1)[-1]
        shell_context = COMMAND_CONTEXT.search(line) is not None
        if token == ' /':
            if command in SHELL or recent.rstrip().endswith('>'):
                value = 1.0
        elif command in SHELL or (command in SHELL_ACTIONS and shell_context):
            if command in ('grep', 'tail'):
                value = 3.1
            else:
                value = 2.3 if token == ' --' else 2.5
        elif token == ' --' and (shell_context or re.search(r'\s--[A-Za-z]', line)):
            value = 2.1
        elif re.search(r'\.(?:py|rs|sh|js|go)\s*$', recent):
            value = 2.1 if token == ' --' else 0.7
        elif token == ' -' and re.search(r'\[\s*!\s*$', recent):
            value = 2.0
    elif token == '.com' and re.search(r'https?://[^\s/]*$', recent):
        value = 0.5
    elif token == '5':
        if prev_token == '.':
            value = -0.185
        elif prev_token.isdigit():
            value = 0.06
        elif prev_token and prev_token[-1].isalpha():
            value = 0.44
        else:
            value = 0.16 if prev_token.isspace() else 0.1
    return (doc, (recent + token)[-300:]), value

programs.haiku:
"""layers.1.mlp.down_proj:1016 -- a "command-line flag" detector, with a few pronoun quirks.

What it does, in plain terms:
- Main job: it fires on the dash of a command-line option ("grep -E", "tail -10",
  "cat -n", "npm test --coverage") when the dash sits inside a shell command: a tool call
  ("command": "...") or a line that names a known command. Strongest for -/-- after
  grep, tail, head, cat, find, python, pytest. Also weakly on a path slash ("cd /testbed")
  and on a pipe "|" inside such a command. Minus signs in maths or prose stay near zero.
- Pronoun quirks: "it" (weakly, higher after what/when/make/which/how), German "es" and
  Dutch/French/Danish "het/il/det" (subject pronouns), and Russian "на" (on/onto).
- Degenerate filler: a run of the middle-dot token "··" (seen once, in a 512-token row)
  is strongly negative. Digit 5 is slightly positive.
Everything else predicts 0. Predictions are in the component's activation units.
"""

READS = ()

SHELL_MARKS = ('"command": "', "execute_bash")
COMMANDS = {"grep", "egrep", "cat", "head", "tail", "sed", "awk", "find", "python", "python3",
            "pytest", "npm", "npx", "yarn", "pip", "pip3", "apt-get", "apt", "git", "docker",
            "curl", "wget", "cargo", "mvn", "node", "java", "ls", "rm", "xargs", "wc", "sort",
            "tar", "chmod", "sudo", "timeout", "jest", "rustc", "lerna", "kubectl", "ssh", "bash"}
FLAG_VALUES = {" -": 2.0, " --": 2.2, " /": 0.9, " |": 0.6}
IT_BOOST_AFTER = {" what", " when", " make", " made", " makes", " making", " which", " how", " where"}
WORD_VALUES = {
    " it": 0.4, " It": 0.3, " il": 0.4, " Il": 0.5, " het": 1.0, " det": 0.5, " Det": 0.5,
    " es": 1.5, " Es": 1.5, " на": 1.0, " На": 1.2, "5": 0.1,
}


def in_shell_line(prefix):
    """True if the current line (back to the last newline, at most 80 tokens) is a shell
    command: it has a tool-call "command" field, or names a known command."""
    words = []
    for s in reversed(prefix.token_strings[:-1]):
        if "\n" in s or len(words) > 80:
            break
        words.append(s)
    text = "".join(reversed(words))
    if any(mark in text for mark in SHELL_MARKS):
        return True
    return any(w in COMMANDS for w in text.replace("|", " ").replace("`", " ").split())


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if tok == "··":
        return carry, -1.3
    if tok in FLAG_VALUES and in_shell_line(prefix):
        return carry, FLAG_VALUES[tok]
    if tok == " it" and prev in IT_BOOST_AFTER:
        return carry, 1.0
    return carry, WORD_VALUES.get(tok, 0.0)

programs.sol:
"""A sparse lexical and document-format approximation, not a full predictor.

'Often' and its Chinese counterpart, weaker frequency adverbs, package
names, and '.info' receive positive values. Repeated middle dots are strong.
At document starts, case, digits and the article 'the' set a baseline;
an initial 'Title:' has a particularly large response on its colon.
Everything else is assigned zero, leaving token-specific variation unmodeled.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        position, previous = carry[1] + 1, carry[2]

    word = token.strip()
    if position == 1 and previous == 'Title' and token == ':':
        value = 3.55
    elif position == 0 and token == 'Title':
        value = -0.27
    elif word and set(word) == {'·'} and len(word) >= 2:
        value = 1.98
    elif word == 'often':
        value = 0.62
    elif word == 'Often':
        value = 0.43
    elif word == '往往':
        value = 0.33
    elif word.lower() in {'frequently', 'usually', 'sometimes'}:
        value = 0.10
    elif token == '.info':
        value = 0.50
    elif word.strip('./_').lower() == 'pkg':
        value = 0.34
    elif word.strip('./_').lower() in {'package', 'packages'}:
        value = 0.23
    elif position == 0:
        if word.lower() == 'the':
            value = 0.49
        elif word.isdigit():
            value = 0.28
        elif not word:
            value = 0.0
        elif word.isascii() and word.isalpha() and word[0].isupper():
            value = 0.23
        else:
            value = 0.13
    else:
        value = 0.0
    return (doc, position, token), value

"""A partial, local construction model, not a general sentiment detector.

It gives large values to expressive inability, emphatic 'no', and evaluative
phrases. Literal absence of outcomes and action-anaphoric 'do so' get negative
values. A few Japanese/Chinese negation constructions are also recognized.
Coefficients come from training activations. Unlisted constructions and most
word-specific effects are omitted. State is just 120 recent characters and
is reset at document boundaries.
"""
from functools import lru_cache
import re
import wordnet

READS = ()
BE = {'is', 'are', 'was', 'were', 'be', 'been', 'being', 'am'}
HAVE = {'have', 'has', 'had'}
DO = {'do', 'does', 'did', 'done', 'doing'}
DEGREE = {'very', 'really', 'quite', 'particularly', 'especially', 'too'}
REQUESTS = {'idea', 'question', 'suggestion', 'advice', 'recommendation', 'tip'}
OUTCOMES = {'solution', 'effect', 'change', 'answer', 'value'}
ABSENCE = {'reason', 'sense', 'need', 'use', 'point', 'choice', 'option',
           'plan', 'evidence', 'sign', 'regard', 'permission', 'insight'}
# Conventional emphatic denials, including understatements such as 'no small'.
EMPHATIC_NO = {'small', 'less', 'different', 'new', 'good', 'fun', 'secret',
               'joke', 'surprise', 'kidding', 'doubt', 'shortage', 'two', 'means'}
EXPRESSIVE = {'wait', 'help', 'resist', 'stand', 'believe'}
EVALUATIVE = {'good', 'bad', 'great', 'big', 'huge', 'high', 'low',
              'easy', 'difficult', 'hard', 'top'}
EVALUATED_NOUN = {'fan', 'deal', 'idea', 'task', 'priority', 'maintenance'}

@lru_cache(maxsize=50000)
def lexical(word):
    roots = wordnet.base_forms(word)
    return (roots[0] if roots else word), wordnet.parts_of_speech(word)


def predict(before, token):
    w = token.strip().lower()
    words = before.lower().replace('’', "'").replace('\\', '').split()
    prev = words[-1] if words else ''
    for suffix, full in [("'s", 'is'), ("'re", 'are'),
                         ("'m", 'am'), ("'ve", 'have')]:
        if prev.endswith(suffix):
            prev = full
            break
    value = -0.065 if not before else 0.0015
    if (re.search(r'(?:ない|ません)$', before)
            and token in {'で', 'と', 'とい', 'ほど'}):
        value += 3.31
    if w == '错过' and before.endswith(('不要', '别', '不能')):
        value += 2.89  # Chinese 'do not miss'.
    if not w.isascii() or not w.isalpha():
        return value

    contracted = prev.endswith("n't") or prev == 'cannot'
    neg = contracted or prev == 'not'
    near = any(x in {'not', 'no', 'never', 'cannot'} or x.endswith("n't")
               for x in words[-5:])
    root, pos = lexical(w) if near or prev == 'any' else (w, ())
    if w == 'not' and prev in BE | HAVE: value += 0.065
    if w == 'no':
        value += 0.06
        if prev in BE | HAVE: value -= 0.28
        if len(words) > 1 and words[-2] == 'there' and prev in BE:
            value -= 0.46
        if prev in {'say', 'said', 'saying', 'says'}: value += 0.99
    if w == 'cannot': value -= 0.08
    if w in {'nothing', 'anything'}: value -= 0.37
    if w == 'any':
        value -= 0.045
        if prev == 'without': value -= 0.35

    # Expressive inability differs from ordinary contracted negation.
    if contracted:
        value += 0.07
        if 'verb' in pos: value += 0.10
        if w in EXPRESSIVE: value += 0.85
        if w == 'let': value += 2.67
    if prev in {"can't", "couldn't", 'cannot'}:
        value += 0.41
        if w in EXPRESSIVE: value += 2.10
    if neg:
        value += 0.077
        if w == 'be': value += 0.27
        if w in DEGREE: value += 0.42
        if w in {'only', 'even', 'necessarily', 'specifically',
                 'practically', 'so'}:
            value -= 0.32
        if w in {'easy', 'difficult', 'alone', 'new', 'good', 'true'}:
            value += 1.41
    if near and w in {'lightly', 'readily', 'easily'}: value += 1.57
    if any(x in {'no', 'without'} for x in words[-2:]):
        root, _ = lexical(w)
        if root in OUTCOMES: value -= 1.43
        if root in ABSENCE: value -= 0.43
    if prev == 'any' and root in OUTCOMES: value -= 0.55
    if prev == 'no':
        if w in EMPHATIC_NO: value += 1.81
        if w in {'other', 'such', 'further', 'more'}: value -= 0.26
        if w == 'time': value += 0.62
    if root in REQUESTS and prev == 'any': value += 1.03

    # Evaluative idioms and a few short grammatical constructions.
    if prev in EVALUATIVE and w in EVALUATED_NOUN:
        # 'Good/great deal' expresses quantity, unlike 'big deal'.
        value += -0.59 if w == 'deal' and prev in {'good', 'great'} else 2.14
    if w == 'of' and prev == 'fan': value += 2.44
    if (w == 'recommend'
            and prev in {'highly', 'strongly', 'definitely', 'really'}):
        value += 2.87
    if w == 'next' and prev in {'the', 'is'}: value += 0.24
    if w in {'less', 'new'} and prev in {'nothing', 'anything'}:
        value += 2.70
    if w == 'but' and prev in {'help', 'nothing', 'anything'}: value += 1.12
    if w == 'so' and prev in DO: value -= 1.53
    if w == 'bit' and prev == 'little': value -= 0.93
    if w == 'without' and (near or prev == 'incomplete'): value += 1.85
    if w == 'soon' and prev == 'anytime': value += 2.98
    if w in {'part', 'place', 'care'} and lexical(prev)[0] == 'take':
        value -= 0.59
    if w == 'to' and prev in {'able', 'ability', 'unable', 'impossible'}:
        value -= 0.19
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, (before + token)[-120:]), float(predict(before, token))

"""Detect short 'ep' fragments, including e|p across a token boundary.

The signal is negative, strongest at a fragment's end. Common English words
and doubled-e spellings suppress it. English word frequency and the amount
of text after p set its rough size. Transliteration extends the spelling
rule to Greek and Cyrillic. A repeated p in pep strengthens the signal.
Two independent negative triggers are the colon of a document-initial
'Title:' header and a double middle dot.
"""
import re
import regex
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=12000)
def describe(text):
    # Avoid interpreting, for example, a Chinese character's romanized
    # syllable as a literal sequence of alphabetic letters.
    other_letters = regex.search(
        r'(?V1)[\p{L}--[\p{Script=Latin}\p{Script=Greek}'
        r'\p{Script=Cyrillic}]]', text)
    if other_letters:
        return '', []
    letters = anyascii(text).lower()
    return letters, re.findall('[a-z]+', letters)

@lru_cache(maxsize=12000)
def frequency(word):
    return zipf_frequency(word, 'en')


def ep_value(part, joined, doubled, cross, previous_length):
    at = part.rfind('ep')
    tail = len(part) - at - 2
    f = frequency(part)
    if cross:
        if f <= .5:
            return -.38
        if previous_length > 3:
            return -.99
        return -4.75 if tail == 0 else -2.50
    if tail == 0:
        if f > 4.5:
            return -.06
        if doubled:
            return .12
        if f <= 1.5:
            return -.13
        return -2.42 if f <= 4 else -3.39
    if frequency(joined) > 3.5:
        return -.09
    return -1.26 if tail == 1 else -.28


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position = '', 0
    else:
        previous, position = carry[1], carry[2] + 1
    text = prefix.token_strings[-1]
    low, parts = describe(text)
    old, old_parts = describe(previous)
    cross = low.startswith('p') and old.endswith('e')
    part = next((p for p in parts if 'ep' in p), '')
    if cross:
        part = 'e' + parts[0]
    value = 0.0
    if part:
        joined = part
        if (low[0].isalpha() and old and old[-1].isalpha()
                and old_parts):
            joined = old_parts[-1] + parts[0]
        at = part.rfind('ep')
        doubled = ((at > 0 and part[at - 1] == 'e')
                   or (low.startswith('ep') and old.endswith('e')))
        previous_length = len(old_parts[-1]) if old_parts else 0
        value = ep_value(part, joined, doubled, cross, previous_length)
        if 'pep' in part or (cross and old.endswith('pe')):
            value *= 1.9
    if text == ':' and position == 1 and previous == 'Title':
        value = -15.72
    if text == '··':
        value = -3.18
    return (doc, text, position), float(value)

"""Estimate a short-aside closing signal, not punctuation in general.

Keep 64 recent tokens, resetting between documents. Look for the most recent
matching opening mark (or comma/dash). Openers following a space are treated
as prose insertions, unlike most function-call parentheses. The strongest
negative values mark brief lowercase insertions, especially alternatives
starting with a conjunction. Case, numeric content, word frequency and span
length modulate the estimate. Comma-delimited adverbial/conditional asides
and unspaced typographic quotation marks have separate, weaker rules.
"""
import re
import unicodedata
from functools import lru_cache
import wordnet
from wordfreq import zipf_frequency

READS = ()
OPENERS = {
    ')': '(', '）': '（', ']': '[', '}': '{', '］': '［', '｝': '｛',
    '」': '「', '』': '『', '】': '【', '》': '《', '〉': '〈',
    '”': '“', '’': '‘', '"': '"', "'": "'", '`': '`', '*': '*',
}
TYPOGRAPHIC = frozenset('）］｝」』】》〉”’')


@lru_cache(maxsize=4096)
def adverb(word):
    return 'adverb' in wordnet.parts_of_speech(word.lower())


def response(token, tokens):
    z = token.lstrip()
    if not z:
        return 0.0
    c = z[0]
    if c not in OPENERS and c not in ',，—–':
        if z[-1] in OPENERS and all(
            unicodedata.category(x).startswith('P') or x == '%' for x in z
        ):
            c = z[-1]
        else:
            return 0.0
    comma, dash = c in ',，', c in '—–'
    before = ''.join(tokens)
    opening = before.rfind(c if comma or dash else OPENERS[c])
    if opening < 0:
        return 0.0
    span = before[opening + 1:]
    distance, characters = 0, 0
    for old in reversed(tokens):
        distance += 1
        characters += len(old)
        if characters > len(span):
            break
    words = re.findall(r'[^\W\d_]+', span)
    first = words[0].lower() if words else ''
    match = re.search(r'([^\W\d_]+)\s*$', before)
    word = match.group(1) if match else ''
    letters = ''.join(ch for ch in span if ch.isalpha())
    spaces = sum(ch.isspace() for ch in span)
    prose = opening > 0 and before[opening - 1].isspace()
    typographic = c in TYPOGRAPHIC

    if not prose:
        if distance > 6:
            return 0.0
        if first == 'or':
            return -2.78 if comma else 0.0
        since_comma = next(
            (i + 1 for i, t in enumerate(reversed(tokens)) if ',' in t), 100
        )
        if adverb(first):
            return -0.98 if word.islower() and since_comma <= 4 else -0.2
        if typographic:
            return -1.95 if len(token) == 1 else -0.39
        if first == 'if':
            return -2.8 if since_comma <= 5 else -0.22
        return 0.0

    if len(token) > 1:
        return (-2.42 if distance <= 3 else -0.22) if dash else 0.0
    if len(word) <= 1:
        return 0.62 if sum(ch.isdigit() for ch in span) > 4 else -0.19
    # Word-internal apostrophes and hyphens are not phrase boundaries.
    cleaned = re.sub(r"(?<=\w)[\-’'](?=\w)", '', span)
    if any(unicodedata.category(ch).startswith('P') for ch in cleaned):
        return -0.24
    emphasis = c in '*`'
    bracket = c in ']}］｝】》〉'
    if not letters.islower():
        if spaces > 1:
            return -0.51
        return -0.27 if bracket or emphasis else -1.84
    if first in ('and', 'or', 'but'):
        return -6.35
    if distance > 5:
        return -0.95
    if emphasis:
        return -0.47
    if bracket:
        return -0.73
    if typographic:
        return -4.25
    if len(word) <= 3:
        return -1.25 if zipf_frequency(word.lower(), 'en') <= 5.15 else -3.37
    if spaces:
        return -2.48
    return -4.19 if c in ')）' else -2.95


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    tokens = carry[1] if carry is not None and carry[0] == document else ()
    token = prefix.token_strings[-1]
    value = response(token, tokens)
    return (document, (tokens + (token,))[-64:]), float(value)

programs.haiku:
"""Closing punctuation of a short aside, as a negative value.

Layer 1 MLP unit that goes strongly negative on the token that closes an
inserted aside in the middle of a sentence: the ")" or "）" or "」" or "”"
ending a short bracketed or quoted phrase such as "(most)", "(but not all)"
or "(if any)". The value is about -2 when the aside is one or two words,
-1 for three to five words, -0.3 if the aside contains a digit (dates,
citations, numbers), and 0 for longer asides. A straight double quote
gets -1.2 and a dash gets -0.6, since both open or close asides too. A
comma that closes an interjection such as "for example," or "however,"
(at most three words, no digits, within eight tokens of an earlier comma)
gets -1.2. Everything else is 0. The program reads only the prefix; the
state it keeps is the stack of open brackets in the current document.
"""

READS = ()

OPENERS = {"(", " (", "（", "“", "「"}
CLOSERS = {")": "(", "）": "（", "」": "「", "”": "“"}
QUOTE_VALUE = -1.2
DASH_VALUE = -0.6
COMMA_VALUE = -1.2
INTERJECTIONS = {
    "or", "and", "but", "for", "however", "say", "indeed", "again", "example",
    "particular", "instance", "perhaps", "if", "not", "in", "too", "also",
    "especially", "certainly", "even", "then", "so", "though", "instead",
    "actually", "now", "still", "really", "only", "just", "yet", "etc",
}


def aside_value(inner):
    if any(c.isdigit() for c in inner):
        return -0.3
    words = len(inner.split())
    if words <= 2:
        return -2.0
    if words <= 5:
        return -1.0
    return 0.0


def is_interjection(inner):
    words = inner.split()
    if any(c.isdigit() for c in inner) or len(words) > 3:
        return False
    return any(w.lower().strip(".,") in INTERJECTIONS for w in words)


def step(carry, prefix, upstream):
    if carry is None or prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        carry = {"open": [], "comma": None}
    tok = prefix.token_strings[-1]
    t = prefix.position
    value = 0.0
    last = tok[-1:]
    if tok in OPENERS:
        carry["open"].append((tok.strip(), t))
    elif last in CLOSERS:
        want = CLOSERS[last]
        for j in range(len(carry["open"]) - 1, -1, -1):
            if carry["open"][j][0] == want:
                start = carry["open"][j][1]
                del carry["open"][j:]
                value = aside_value("".join(prefix.token_strings[start + 1:-1]))
                break
    elif tok == '"':
        value = QUOTE_VALUE
    elif tok in (" —", "—"):
        value = DASH_VALUE
    elif tok == ",":
        previous = carry["comma"]
        if previous is not None and t - previous <= 8:
            inner = "".join(prefix.token_strings[previous + 1:-1])
            if is_interjection(inner):
                value = COMMA_VALUE
        carry["comma"] = t
    if any(ch in tok for ch in ".!?\n;"):
        carry["comma"] = None
    return carry, value

programs.sol:
"""Approximate an I/V/X Roman-numeral fragment feature.

Isolated letters are ambiguous; combinations and continuations of numerals
are stronger, especially after X. Case, word boundaries and numbering cues
modify the score. Most other tokens get zero, with weak punctuation carryover.
"""
import re

READS = ()
NUMBER_CONTEXTS = set('''
chapter chap vol volume book part section article annex appendix division
capitulo capitolo sermon sonnet henry louis charles edward george pius pope
band bd tome secolo siglo siècle t pp tit lib cap spec prodr
'''.split())
CLASS_CONTEXTS = {'type', 'stage', 'class', 'war'}


def activation(token, tail):
    letters = token.strip()
    if not re.fullmatch('[IVXivx]+', letters):
        return None
    upper, n = letters.upper(), len(letters)
    only_i = set(upper) == {'I'}
    opening = tail.rstrip().endswith('(')
    if n == 1:
        value = ({'I': .1, 'V': .75, 'X': .25}[upper]
                 if letters.isupper() else 0.)
    elif only_i:
        value = 1.55 + .25 * (n - 2)
    elif set(upper) == {'X'}:
        value = 5.85 if n == 2 else 1.55  # Longer X runs often stand for blanks.
    elif 'X' in upper:
        value = 7.0 + .7 * (n - 2) + .9 * ('V' in upper)
    else:
        value = 4.6 + .95 * (n - 2)
    if not re.fullmatch(r'X{0,3}(?:IX|IV|V?I{0,3})', upper):
        value *= .15
    if n > 1 and not letters.isupper():
        value *= .33 if letters.islower() else .13
        if letters.islower() and upper.startswith('V') and not opening:
            value *= .47

    continuing = token[0].isalpha() and tail[-1:].isalnum()
    match = re.search(r'[A-Za-z0-9_]+$', tail) if continuing else None
    word = match.group() if match else ''
    numeral = bool(re.fullmatch('[IVXLCDMivxlcdm]+', word))
    same_case = ((letters.isupper() and word.isupper()) or
                 (letters.islower() and word.islower()))
    if numeral and same_case:
        if 'X' in word.upper():
            value += 10.0 + 5.0 * (letters == 'I')
        else:
            value += 6.5 if 'V' in word.upper() and only_i else .5
    elif continuing:
        value *= .14
        if letters.isupper() and word.isupper():
            if word.endswith('X'):
                value += 5.0
            elif only_i and word.endswith(('I', 'V')):
                value += 2.0

    words = re.findall(r'[^\W\d_]+', tail.lower())
    cue = words[-1] if words else ''
    if cue in NUMBER_CONTEXTS or cue in CLASS_CONTEXTS:
        value += 1.4
        if n == 1 and letters.isupper() and cue in NUMBER_CONTEXTS:
            value += 1.0 * (cue != 't' or tail.rstrip().endswith('.'))
    value += 4.2 * (opening and letters == 'iv')
    if re.search(r'[\\_$^={]$', tail.rstrip()):
        value *= .58
    return value


def step(carry, prefix, upstream):
    document, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != document:
        carry = (document, '', 0.)
    _, tail, previous = carry
    value = activation(token, tail)
    if value is None:
        punctuation = token.strip()
        is_punctuation = punctuation and all(c in '.,;:)]' for c in punctuation)
        value = .08 * previous if is_punctuation else 0.
    return (document, (tail + token)[-100:], value), float(value)

"""Detect densely tokenized encoded identifiers, rather than ordinary prose.

An unbroken Base64-alphabet run is convincing when many of its last twelve
pieces are short and it mixes upper and lower case. Long hexadecimal runs
get a smaller positive response. A second, signed response distinguishes
selected numerical values, including number words and calendar ordinals.
State resets at document boundaries.
The initial run of identical tokens has separate estimates for code
declarations, conversation labels, comments, heading depth, and control
characters. These are partial rules, not a model of the lexical background.
"""
import re
import calendar
import unicodedata
import inflect

READS = ()

# Responses to numerical values, independent of their token IDs.
NUMBER_RESPONSE = {
    5: -0.13,
    11: -0.23,
    15: -0.16,
    21: -0.23,
    31: -0.10,
    65: -0.18,
}
_engine = inflect.engine()
NUMBER_WORDS = {}
for _n in NUMBER_RESPONSE:
    for _form in (_engine.number_to_words(_n),
                  _engine.number_to_words(_engine.ordinal(_n))):
        NUMBER_WORDS[_form] = _n
        NUMBER_WORDS[_engine.plural_noun(_form)] = _n
MONTHS = {name: n for n, name in enumerate(calendar.month_name) if name}
MONTH_ABBREVIATIONS = {
    name: n for n, name in enumerate(calendar.month_abbr) if name
}
WEEKDAYS = {name: n + 1 for n, name in enumerate(calendar.day_name)}
BASE64_PIECE = re.compile(r'[A-Za-z0-9+/]+\Z')
HEX_PIECE = re.compile(r'[A-Fa-f0-9]+\Z')


def ramp(x):
    return max(0.0, min(1.0, x))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    if first:
        run, hexadecimal, number, opening = [], [], '', True
    else:
        _, run, hexadecimal, number, previous, opening = carry
        opening = opening and token == previous
    is_digit = len(token) == 1 and token in '0123456789'
    number = (number + token)[-16:] if is_digit else ''
    run = (run + [token])[-12:] if BASE64_PIECE.fullmatch(token) else []
    hexadecimal = ((hexadecimal + [token])[-24:]
                   if HEX_PIECE.fullmatch(token) else [])
    text = ''.join(run)
    upper = sum(c.isupper() for c in text)
    lower = sum(c.islower() for c in text)
    changes = sum(a.isupper() != b.isupper()
                  for a, b in zip(text, text[1:])
                  if a.isalpha() and b.isalpha())
    short = sum(len(piece) <= 2 for piece in run)
    value = 0.0004
    if upper >= 2 and lower >= 2 and changes:
        value += 0.655 * ramp((short - 6) / 6)

    hex_text = ''.join(hexadecimal)
    digits = sum(c.isdigit() for c in hex_text)
    if digits >= 3 and len(hex_text) - digits >= 3:
        value += 0.162 * ramp((len(hexadecimal) - 4) / 12)

    # Decimal prefixes have a few strong signed numerical responses.
    if is_digit:
        n = int(number)
        if n == 5:
            value -= 0.045
        elif n in {11, 21, 31}:
            value += NUMBER_RESPONSE[n]
        elif n % 100 == 65 and len(number) <= 3:
            value -= 0.18
        elif token not in '15':
            value += 0.01

    # Recognize numerical meanings without a token-ID table.
    word = token.strip()
    n = NUMBER_WORDS.get(word.casefold())
    if n is None and len(word) == 1:
        n = unicodedata.numeric(word, None)
    if not is_digit and n in NUMBER_RESPONSE:
        value += NUMBER_RESPONSE[n]
    if word in MONTHS:
        n = MONTHS[word]
        scale = 0.4 if n == 5 else 1.0
        value += scale * NUMBER_RESPONSE.get(n, 0.0)
    elif word in MONTH_ABBREVIATIONS:
        value += 0.55 * NUMBER_RESPONSE.get(MONTH_ABBREVIATIONS[word], 0.0)
    elif word in WEEKDAYS:
        value += NUMBER_RESPONSE.get(WEEKDAYS[word], 0.0)

    # Initial formatting overrides the ordinary-context estimates.
    if opening:
        value = -0.15 if is_digit and token != '0' else -0.04
        if token == 'from':
            value = 1.46
        elif token == 'public':
            value = 1.10
        elif token in {'def', 'class', 'using'}:
            value = 0.68
        elif token in {'import', 'package'}:
            value = 0.28
        elif token == '\x00':
            value = 1.71
        elif token == '\t':
            value = 0.41
        elif token == r'\t':
            value = -1.03
        elif token == '<|im_start|>':
            value = -0.11
        elif token in {'Person', 'User', 'user'}:
            value = -1.05
        elif token and not token.strip('#'):
            # Markdown heading depth, limited to the observed range.
            value = -0.05 - 0.06 * min(5, len(token)) ** 2
        elif token == '<!':
            value = -2.71
        elif token.startswith('/*'):
            value = -0.55
        elif token == '//':
            value = -0.33
        elif token == '///':
            value = -1.40
    return (doc, run, hexadecimal, number, token, opening), float(value)
